'use strict';
CONTENU.tr={
lecons:{
'r-bienvenue':{titre:"Ramazan ayı",
 texte:["Ramazan, Hicri takvim denilen İslami takvimin 9. ayıdır. Bu takvim kameridir: her ay yeni hilalin görünmesiyle başlar.","Kameri yıl yaklaşık 354 gündür. Bu yüzden Ramazan, kullandığımız takvimde her yıl on gün kadar öne kayar.","Kur'an'ın inmeye başladığı ay budur. Ramazan orucu, Hicret'in 2. yılında farz kılınmıştır."],
 retenir:"Ramazan, 9. kameri aydır; Kur'an'ın ve orucun ayıdır.",
 sources:["q:2:185","h:croissant"],
 quiz:[
  {q:"İslami (Hicri) takvimde Ramazan ayı kaçıncı aydır?",c:["9. ay","1. ay","12. ay","7. ay"],b:0,e:"Ramazan 9. aydır. Hicri yılın 1. ayı Muharrem'dir.",s:["f:mois"]},
  {q:"İslami (Hicri) takvim hangi gök cismine dayanır?",c:["Ay","Güneş","Yıldızlar","Hiçbir gök cismine"],b:0,e:"Her ay yeni hilalin görünmesiyle başlar.",s:["q:2:189","h:croissant"]},
  {q:"Ramazan'ın tarihi neden her yıl yaklaşık 11 gün öne kayar?",c:["Çünkü kameri yıl güneş yılından daha kısadır","Çünkü âlimler onu her yıl kaydırır","Çünkü Hicri yıl 13 aydır","Çünkü İran güneş takvimine uyulur"],b:0,e:"Kameri yıl yaklaşık 354 gündür; yani güneş yılından yaklaşık 11 gün kısadır.",s:["q:9:36"]},
  {q:"Ramazan ayında hangi büyük olay başlamıştır?",c:["Kur'an'ın inişi","Kâbe'nin inşası","Medine'ye Hicret","Uhud Savaşı"],b:0,e:"Kur'an, Ramazan ayında inmeye başlamıştır.",s:["q:2:185"]},
  {q:"İslami (Hicri) yıl kaç aydır?",c:["12","10","13","11"],b:0,e:"Hicri yıl 12 kameri aydır.",s:["q:9:36"]},
  {q:"Hadise göre Ramazan orucuna hangi işaretle başlanır?",c:["Yeni hilal görüldüğünde","Dolunay görüldüğünde","Her yıl 15 Şaban'da","Şaban'dan sonraki ilk cumadan sonra"],b:0,e:"\"Onu gördüğünüzde oruç tutun\": burada kastedilen hilaldir.",s:["h:croissant"]},
  {q:"Ramazan'dan sonra gelen ve ilk günü Ramazan Bayramı olan ayın adı nedir?",c:["Şevval","Şaban","Recep","Muharrem"],b:0,e:"1 Şevval, Ramazan Bayramı'nın ilk günüdür.",s:["f:mois"]},
  {q:"İslami takvimde Ramazan'dan hemen önce hangi ay gelir?",c:["Şaban","Şevval","Zilhicce","Safer"],b:0,e:"Şaban 8. aydır, Ramazan'dan hemen öncedir.",s:["f:mois"]},
  {q:"Ramazan orucu Hicret'in kaçıncı yılında farz olmuştur?",c:["2. yıl","1. yıl","10. yıl","8. yıl"],b:0,e:"Ramazan orucu Medine'de, Hicret'in 2. yılında farz kılınmıştır.",s:["f:jeune2"]},
  {q:"Ramazan ayı kaç gün sürebilir?",c:["29 veya 30 gün","Her zaman 30 gün","28 gün","31 gün"],b:0,e:"Kameri ay, bir sonraki hilalin görünmesine göre 29 veya 30 gün sürer.",s:["h:croissant"]}
 ]},
'r-jeuner':{titre:"Kimler oruç tutmalı?",
 texte:["Ramazan orucu; ergenliğe ermiş, akıllı ve oruç tutmaya gücü yeten Müslümana farzdır.","Hasta ve yolcu oruç tutmayabilir, sonra o günleri kaza eder. Âdet dönemindeki kadın oruç tutmaz, sonra kaza eder.","Hiçbir zaman oruç tutamayacak olan kişi, örneğin çok yaşlı biri, tutamadığı her gün için bir fakiri doyurur: buna fidye denir."],
 retenir:"Kolaylıklar vardır: Allah bizim için kolaylık ister.",
 sources:["q:2:184","q:2:185"],
 quiz:[
  {q:"Ramazan'da bazı günler oruç tutmayan yolcu ne yapmalıdır?",c:["O günleri daha sonra kaza etmelidir","Hiçbir şey yapmamalıdır","Para cezası ödemelidir","İki kat oruç tutmalıdır"],b:0,e:"Ramazan'dan sonra aynı sayıda gün kaza eder.",s:["q:2:184"]},
  {q:"Tutulamayan her oruç günü için bir fakiri doyurmaktan ibaret olan telafinin adı nedir?",c:["Fidye","Sadaka","Fıtır sadakası","Kefaret"],b:0,e:"Fidye özellikle hiçbir zaman kaza edemeyecek kişileri, örneğin çok yaşlıları ilgilendirir.",s:["q:2:184"]},
  {q:"Ergenlik çağına girmemiş bir çocuğa Ramazan orucu farz mıdır?",c:["Hayır, ama ona alıştırılabilir","Evet, 7 yaşından itibaren","Evet, ama sadece cuma günleri","Sadece son on günde"],b:0,e:"Farz değildir. Yine de sahabe, çocuklarını oruca alıştırırdı; örneğin Âşûrâ gününde.",s:["h:enfants"]},
  {q:"Ramazan'da âdet gören kadın ne yapar?",c:["Oruç tutmaz, günleri sonra kaza eder","Yine de oruç tutar","Hiçbir zaman kaza etmez","Günün yarısında oruç tutar"],b:0,e:"Oruç tutmaz, kaçırdığı günleri Ramazan'dan sonra kaza eder.",s:["h:regles"]},
  {q:"Ramazan'da oruç tutmayan hasta, kaçırdığı günleri kaza etmeli midir?",c:["Evet, gücü yettiğinde","Hayır, asla","Evet, ama iki katını","Hayır, her zaman para cezası öder"],b:0,e:"Gücü yettiğinde aynı sayıda günü kaza eder.",s:["q:2:184"]},
  {q:"Âdet gören kadın, bu dönemde kılmadığı namazları kaza etmeli midir?",c:["Hayır, sadece orucu kaza eder","Evet, bütün namazları","Evet, namazların yarısını","Sadece cuma namazını"],b:0,e:"Orucu kaza eder ama namazı kaza etmez.",s:["h:regles"]},
  {q:"Oruç âyetine göre Allah müminler için ne ister?",c:["Kolaylık","Zorluk","Yorgunluk","Zenginlik"],b:0,e:"\"Allah sizin için kolaylık ister, zorluk istemez.\"",s:["q:2:185"]},
  {q:"Bir daha asla oruç tutamayacak çok yaşlı bir kişi ne yapar?",c:["Her gün için bir fakiri doyurur","Yine de oruç tutar","Hiçbir şey yapması gerekmez","Bir sonraki Ramazan'dan sonra kaza eder"],b:0,e:"Bu fidyedir: tutulmayan her gün için bir fakire bir öğün yemek.",s:["q:2:184"]},
  {q:"Ramazan orucu kime farzdır?",c:["Ergenliğe ermiş, akıllı ve oruca gücü yeten Müslümana","Bütün çocuklara","Sadece erkeklere","Sadece hacca gitmiş olanlara"],b:0,e:"Bunlar âlimlerin belirlediği şartlardır.",s:["f:conditions"]},
  {q:"Kur'an'a göre oruç Müslümanlardan önce de farz kılınmış mıdır?",c:["Evet, onlardan öncekilere","Hayır, asla","Sadece Mekke halkına","Sadece Nuh kavmine"],b:0,e:"\"Oruç, sizden öncekilere farz kılındığı gibi size de farz kılındı.\"",s:["q:2:183"]}
 ]},
'r-rompt':{titre:"Orucu bozan şeyler",
 texte:["Oruç, sabah namazı (fecr) vaktinde, tan yerinin ağarmasıyla başlar ve akşam namazı vaktinde, güneşin batmasıyla sona erer.","Gündüz bilerek yemek, içmek veya cinsel ilişkide bulunmak orucu bozar.","Unutarak yiyen ya da içen kişi orucuna devam eder: orucu geçerlidir."],
 retenir:"Unutarak yemek ya da içmek orucu bozmaz.",
 sources:["q:2:187","h:oubli"],
 quiz:[
  {q:"Ramazan orucu günün hangi anında başlar?",c:["Tan yeri ağarınca (fecr)","Gece yarısı","Güneş doğarken","Öğle vakti"],b:0,e:"Oruç, tan yeri ağarıp beyaz iplik siyah iplikten ayırt edilince başlar.",s:["q:2:187"]},
  {q:"Ramazan orucu ne zaman açılır?",c:["Güneş batınca (akşam)","Gece tamamen karardığında (yatsı)","Saat 16.00'da","Gece yarısında"],b:0,e:"Güneş batar batmaz oruç açılır.",s:["h:coucher"]},
  {q:"Oruçlu biri oruçlu olduğunu unutarak su içiyor. Orucu ne olur?",c:["Geçerli kalır","Bozulur","İki katını tutması gerekir","Miktara bağlıdır"],b:0,e:"Orucunu tamamlar: onu yediren ve içiren Allah'tır.",s:["h:oubli"]},
  {q:"Oruçlu biri Ramazan'da gündüz bilerek yemek yerse ne olur?",c:["Orucu bozulur","Hiçbir şey değişmez","Camideyse caizdir","Öğle namazından sonra caizdir"],b:0,e:"Gündüz bilerek yemek orucu bozar.",s:["q:2:187"]},
  {q:"Kur'an'a göre Ramazan gecelerinde ne zamana kadar yenip içilebilir?",c:["Fecrin beyaz ipliği gecenin siyah ipliğinden ayırt edilinceye kadar","Gece yarısına kadar","Güneş doğana kadar","Yatsı namazına kadar"],b:0,e:"Bu, Bakara suresi 187. âyetteki benzetmedir.",s:["q:2:187"]},
  {q:"Oruç âyetinde \"beyaz iplik\" neyi temsil eder?",c:["Tan yerinin aydınlığını","Gerçek bir yün ipliği","Hilali","Akşamın ilk yıldızını"],b:0,e:"Beyaz iplik tan yerinin aydınlığı, siyah iplik gecenin karanlığıdır.",s:["q:2:187"]},
  {q:"Ramazan'da güneş battıktan sonra gece yemek ve içmek caiz midir?",c:["Evet, tan yeri ağarana kadar","Hayır, bütün ay boyunca asla","Sadece su","Sadece teravih namazından sonra"],b:0,e:"Oruç sadece gündüzü kapsar: tan yerinin ağarmasından güneşin batmasına kadar.",s:["q:2:187"]},
  {q:"Hadise göre oruçluyken unutarak yiyen ya da içen kişiyi kim \"yedirmiş ve içirmiştir\"?",c:["Allah","Ailesi","Bir melek","Hiç kimse"],b:0,e:"Orucu geçerlidir: onu yediren ve içiren Allah'tır.",s:["h:oubli"]},
  {q:"Ramazan'ın gündüzlerinde eşler arasında cinsel ilişki caiz midir?",c:["Hayır, orucu bozar","Evet, her zaman","Evet, öğleden sonra","Sadece Âşûrâ gününde"],b:0,e:"187. âyet bunu Ramazan gecelerinde helal kılar; gündüz ise orucu bozar.",s:["q:2:187"]},
  {q:"Oruç gününün bitişini hangi namaz belirler?",c:["Akşam namazı","Sabah namazı","Öğle namazı","Yatsı namazı"],b:0,e:"Akşam namazı, güneş batarken kılınan namazdır; iftar vaktidir.",s:["h:coucher"]}
 ]},
'r-suhur':{titre:"Sahur ve iftar",
 texte:["Sahur, tan yeri ağarmadan önce yenen yemektir. Peygamberimiz ﷺ sahura teşvik etmiştir, çünkü onda bereket vardır.","İftar, güneş batınca orucu açmaktır. Onu geciktirmemek tavsiye edilir.","Sünnet olan, orucu taze hurmayla, o yoksa kuru hurmayla, o da yoksa birkaç yudum suyla açmaktır."],
 retenir:"Sahur tan yerinden önce. İftar güneş batar batmaz, hurmayla.",
 sources:["h:suhur","h:dattes"],
 quiz:[
  {q:"Ramazan'da tan yeri ağarmadan önce yenen yemeğin adı nedir?",c:["Sahur","İftar","Velime","Akika"],b:0,e:"Sahur, gecenin sonunda, sabah namazından önce yenen yemektir.",s:["h:suhur"]},
  {q:"Hadise göre sahur yemeğinde ne vardır?",c:["Bereket","Bir farz","Özel hiçbir şey","Bir imtihan"],b:0,e:"\"Sahura kalkın, çünkü sahurda bereket vardır.\"",s:["h:suhur"]},
  {q:"Peygamberimiz ﷺ orucunu tercihen ne ile açardı?",c:["Hurma","Deve sütü","Harira çorbası","Ekmek"],b:0,e:"Taze hurma, o yoksa kuru hurma, o da yoksa birkaç yudum su.",s:["h:dattes"]},
  {q:"Güneş battıktan sonra orucu açmayı (iftarı) geciktirmek gerekir mi?",c:["Hayır, acele etmek tavsiye edilir","Evet, bir saat","Evet, yatsıya kadar","Hiçbir önemi yoktur"],b:0,e:"Güneş batar batmaz orucu açmak tavsiye edilir.",s:["h:hater"]},
  {q:"Güneş batınca orucu açan yemeğin adı nedir?",c:["İftar","Sahur","Gusül","Zikir"],b:0,e:"İftar, orucu açmaktır.",s:["h:hater"]},
  {q:"Hurma olmadığında Peygamberimiz ﷺ orucunu ne ile açardı?",c:["Birkaç yudum su","Bal","Keçi sütü","İncir"],b:0,e:"Taze hurma, o yoksa kuru hurma, o da yoksa birkaç yudum su.",s:["h:dattes"]},
  {q:"Peygamberimiz ﷺ orucunu akşam namazından önce mi sonra mı açardı?",c:["Namazdan önce","Namazı kıldıktan sonra","Ertesi gün","Yatsı namazından sonra"],b:0,e:"Namaz kılmadan önce birkaç hurmayla orucunu açardı.",s:["h:dattes"]},
  {q:"Hadise göre insanlar iftarda acele ettikleri sürece…",c:["Hayır üzere olurlar","Şüphe içinde olurlar","Tehlikede olurlar","Sevapsız kalırlar"],b:0,e:"\"İnsanlar iftarda acele ettikleri sürece hayır üzere olmaya devam ederler.\"",s:["h:hater"]},
  {q:"Orucun geçerli olması için sahur farz mıdır?",c:["Hayır, ama çok tavsiye edilir","Evet, yoksa oruç bozulur","Evet, sadece ilk gün","Haramdır"],b:0,e:"Sünnettir: Peygamberimiz ﷺ bereketi için sahura teşvik etmiştir.",s:["h:suhur"]},
  {q:"Peygamberimiz ﷺ oruç açmak için hangi tür hurmayı tercih ederdi?",c:["Taze hurma (rutab)","Kuru hurma (temr)","Kuru incir","Kuru üzüm"],b:0,e:"Taze hurmayla başlardı; o yoksa kuru hurmayla.",s:["h:dattes"]}
 ]},
'r-merites':{titre:"Orucun faziletleri",
 texte:["Allah orucu, mümin takvaya, yani her işinde Allah'ın bilincinde olmaya ulaşsın diye farz kılmıştır.","Peygamberimiz ﷺ, Ramazan orucunu inanarak ve Allah'ın mükâfatını umarak tutan kişinin geçmiş günahlarının bağışlanacağını müjdelemiştir.","Ayın sonunda her Müslüman, bayram namazından önce fıtır sadakasını verir. O, oruçluyu arındırır ve fakirleri doyurur."],
 retenir:"Oruç takvaya götürür. Fıtır sadakası bayram namazından önce verilir.",
 sources:["q:2:183","h:pardon","h:fitr"],
 quiz:[
  {q:"Kur'an'a göre Allah orucu hangi amaçla farz kılmıştır?",c:["Takvaya ulaşmak için","Sadece bedeni arındırmak için","Hicret'i anmak için","Zekâtın yerini tutması için"],b:0,e:"Orucu farz kılan âyet, takvaya ulaşma ümidiyle sona erer.",s:["q:2:183"]},
  {q:"Hadise göre Ramazan orucunu inanarak ve Allah'ın mükâfatını umarak tutan ne kazanır?",c:["Geçmiş günahları bağışlanır","Artık namaz kılmasına gerek kalmaz","Zekâttan muaf olur","Özel hiçbir şey"],b:0,e:"Geçmiş günahları bağışlanır.",s:["h:pardon"]},
  {q:"Fıtır sadakası ne zaman verilmelidir?",c:["Ramazan Bayramı namazından önce","Ramazan'dan bir ay sonra","Sadece Ramazan'ın başında","Yılın herhangi bir zamanında"],b:0,e:"Peygamberimiz ﷺ, insanlar bayram namazına çıkmadan önce verilmesini emretmiştir.",s:["h:fitr"]},
  {q:"\"Takva\" kelimesi ne anlama gelir?",c:["Allah'tan sakınma, Allah bilinci","Sabır","Şükür","Tövbe"],b:0,e:"Takva, insanı iyiliğe sevk eden, Allah'a karşı saygı dolu bir korkudur.",s:["q:2:183"]},
  {q:"Fıtır sadakasını kim vermelidir?",c:["Küçük büyük, erkek kadın her Müslüman","Sadece zenginler","Sadece erkekler","Sadece bütün ay oruç tutanlar"],b:0,e:"Hadis onu her Müslümana farz kılar; aile reisi ailesi adına verir.",s:["h:fitr"]},
  {q:"Hadis fıtır sadakası için ne kadar yiyecek belirler?",c:["Bir sâ'","Bir miskal altın","Bir müd buğday","Bir dirhem gümüş"],b:0,e:"Bir sâ', iki avucun yaklaşık dört katı kadar bir ölçüdür.",s:["h:fitr"]},
  {q:"İbn Ömer'in rivayet ettiği fıtır sadakası hadisinde hangi yiyecekler geçer?",c:["Hurma veya arpa","Pirinç veya kuskus","Et veya balık","Süt veya bal"],b:0,e:"Bir sâ' hurma veya bir sâ' arpa.",s:["h:fitr"]},
  {q:"Hadise göre Ramazan orucu hangi şartlarla geçmiş günahları siler?",c:["İnanarak ve Allah'ın mükâfatını umarak","Sessizce oruç tutarak","40 gün oruç tutarak","Hiçbir şart olmadan"],b:0,e:"İnanarak ve Allah'ın mükâfatını umarak oruç tutmak gerekir.",s:["h:pardon"]},
  {q:"İbn Abbas'ın hadisine göre fıtır sadakasının amacı nedir?",c:["Oruçluyu arındırmak ve fakirleri doyurmak","Cami inşaatını finanse etmek","Hastaların orucunun yerini tutmak","Teravih imamını ödüllendirmek"],b:0,e:"Oruçluyu boş sözlerden arındırır ve fakirleri doyurur.",s:["h:fitr_but"]},
  {q:"Ramazan orucunu farz kılan âyet hangi hitapla başlar?",c:["\"Ey iman edenler!\"","\"Ey insanlar!\"","\"Ey Peygamber!\"","\"Ey Âdemoğlu!\""],b:0,e:"Bakara suresinin 183. âyeti \"Ey iman edenler!\" diye başlar.",s:["q:2:183"]}
 ]},
'r-nuits':{titre:"Ramazan geceleri",
 texte:["Ramazan geceleri daha çok namaz kılma fırsatıdır. Bu gecelerin namazına teravih denir. Peygamberimiz ﷺ, Ramazan gecelerini inanarak ve mükâfatını umarak namazla geçirene bağışlanmayı müjdelemiştir.","Son on gecede gayretini artırırdı: geceyi namazla ihya eder ve ailesini uyandırırdı.","Ayrıca itikâfa girerdi: son on günde camide manevi bir inziva. Bunu ömrünün sonuna kadar sürdürdü."],
 retenir:"Teravih, son on gece, itikâf: Ramazan geceleri namazla yaşanır.",
 sources:["h:qiyam","h:dixnuits","h:itikaf"],
 quiz:[
  {q:"Ramazan'da kılınan gece namazına ne denir?",c:["Teravih","Kuşluk namazı","İstihare namazı","Cenaze namazı"],b:0,e:"Teravih, Ramazan gecelerinin namazıdır.",s:["h:qiyam"]},
  {q:"Hadise göre Ramazan gecelerini inanarak ve mükâfatını umarak namazla geçiren ne kazanır?",c:["Geçmiş günahları bağışlanır","Camide ilk safta bir yer","Artık oruç tutması gerekmez","Özel hiçbir şey"],b:0,e:"Geçmiş günahları bağışlanır.",s:["h:qiyam"]},
  {q:"İtikâf nedir?",c:["Camide manevi bir inziva","Mekke'ye bir yolculuk","Âşûrâ orucu","Bir sadaka"],b:0,e:"İbadete yoğunlaşmak için camide kalınır.",s:["h:itikaf"]},
  {q:"Peygamberimiz ﷺ Ramazan'ın hangi döneminde itikâfa girerdi?",c:["Son on günde","İlk on günde","Sadece ilk gün","Bayramdan sonra"],b:0,e:"Ramazan'ın son on gününde itikâfa girerdi.",s:["h:itikaf"]},
  {q:"Peygamberimiz ﷺ Ramazan'ın son on gecesinde ne yapardı?",c:["Namazla geceyi ihya eder ve ailesini uyandırırdı","Yolculuğa çıkardı","Daha erken uyurdu","Oruç tutmayı bırakırdı"],b:0,e:"İbadette gayretini artırırdı.",s:["h:dixnuits"]},
  {q:"Peygamberimiz ﷺ ömrünün sonuna kadar itikâfa girdi mi?",c:["Evet, vefatına kadar","Hayır, sadece bir kez","Hayır, hiç","Sadece Mekke'de"],b:0,e:"Hz. Âişe, Allah onu yanına alıncaya kadar itikâfa girdiğini rivayet eder.",s:["h:itikaf"]},
  {q:"İtikâf nerede yapılır?",c:["Camide","Evde","Hira mağarasında","Mezarlıkta"],b:0,e:"Kur'an, mescitlerde itikâfta olanlardan bahseder.",s:["q:2:187"]},
  {q:"Ramazan'ın son on gecesi arasında hangi çok önemli gece vardır?",c:["Kadir Gecesi","Hicret gecesi","Kurban Bayramı gecesi","Mevlid gecesi"],b:0,e:"Son on gecenin tek gecelerinde aranmalıdır.",s:["h:qadr"]},
  {q:"Teravih namazı farz mıdır?",c:["Hayır, çok tavsiye edilen nafile bir namazdır","Evet, beş vakit namaz gibi","Evet, ama sadece camide","Haramdır"],b:0,e:"Peygamberimiz ﷺ onu birkaç gece cemaatle kıldı, sonra farz olur korkusuyla bıraktı.",s:["h:tarawih"]},
  {q:"Peygamberimiz ﷺ birkaç geceden sonra teravihi cemaatle kıldırmayı neden bıraktı?",c:["Farz olur korkusuyla","Hasta olduğu için","Cami çok küçük olduğu için","Ramazan bittiği için"],b:0,e:"Ümmetine farz kılınmasından endişe etti.",s:["h:tarawih"]}
 ]},
'r-qadr':{titre:"Kadir Gecesi",
 texte:["Kadir Gecesi, Kur'an'ın inmeye başladığı gecedir.","Allah onun \"bin aydan daha hayırlı\" olduğunu bildirir. Melekler o gece iner ve o gece tan yeri ağarıncaya kadar esenliktir. Bir surenin tamamı ona ayrılmıştır: Kadir suresi (97).","Ramazan'ın son on gecesinde, özellikle tek gecelerde, namaz ve duayı çoğaltarak aranır."],
 retenir:"Bin aydan daha hayırlı. Son on gecenin tek gecelerinde aranır.",
 sources:["q:97:1","q:97:3","h:qadr"],
 quiz:[
  {q:"Kur'an'a göre Kadir Gecesi ne kadar zamandan daha hayırlıdır?",c:["Bin ay","Yüz gün","Bir yıl","On gece"],b:0,e:"Bin aydan, yani 83 yıldan fazla bir süreden daha hayırlıdır.",s:["q:97:3"]},
  {q:"Kur'an'daki hangi sure Kadir Gecesi'ne ayrılmıştır?",c:["Kadir suresi","Fâtiha suresi","İhlâs suresi","Yâsîn suresi"],b:0,e:"97. sure olan Kadir suresi, adını bu geceden alır.",s:["q:97:1"]},
  {q:"Kadir Gecesi öncelikle Ramazan'ın hangi gecelerinde aranmalıdır?",c:["Son on gecenin tek gecelerinde","İlk on gecede","İlk gecede","Bayram gecesinde"],b:0,e:"Son on gecenin tek geceleri: 21, 23, 25, 27 ve 29.",s:["h:qadr"]},
  {q:"Kadir Gecesi'nde hangi olay gerçekleşmiştir?",c:["Kur'an'ın inişinin başlaması","Medine'ye Hicret","Peygamberimiz ﷺ'in doğumu","İlk hac"],b:0,e:"Kur'an bu gecede inmeye başlamıştır.",s:["q:97:1"]},
  {q:"Kadir suresine göre Kadir Gecesi'nde kimler iner?",c:["Melekler ve Ruh (Cebrail)","Peygamberler","Cinler","Hiç kimse"],b:0,e:"Melekler ve Ruh, Rablerinin izniyle o gece iner.",s:["q:97:4"]},
  {q:"Kadir suresine göre Kadir Gecesi ne zamana kadar esenliktir?",c:["Tan yeri ağarıncaya kadar","Gece yarısına kadar","Ramazan'ın sonuna kadar","Bayrama kadar"],b:0,e:"\"O gece, tan yerinin ağarmasına kadar bir esenliktir.\"",s:["q:97:5"]},
  {q:"Kadir suresi kaç âyettir?",c:["5","7","3","10"],b:0,e:"Kadir suresi 5 âyettir.",s:["q:97:5"]},
  {q:"Bin ay yaklaşık kaç yıl eder?",c:["83 yıldan fazla","10 yıl","40 yıl","1000 yıl"],b:0,e:"1000 ay ÷ 12 ≈ 83 yıl 4 ay: bir ömürden bile fazla.",s:["q:97:3"]},
  {q:"Ramazan'ın son on gecesinin tek geceleri hangileridir?",c:["21, 23, 25, 27 ve 29","20, 22, 24, 26 ve 28","1, 3, 5, 7 ve 9","11, 13, 15, 17 ve 19"],b:0,e:"Bunlar Kadir Gecesi'ni aramak için tavsiye edilen gecelerdir.",s:["h:qadr"]},
  {q:"Peygamberimiz ﷺ Hz. Âişe'ye Kadir Gecesi için hangi duayı öğretti?",c:["\"Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî\"","\"Bismi Llâh\"","\"Allâhu akbar\"","\"Subḥâna Llâh\""],b:0,e:"\"Allah'ım, Sen affedicisin, affetmeyi seversin, beni de affet.\"",s:["h:afw"]}
 ]},
'r-aid':{titre:"Ramazan Bayramı",
 texte:["Ramazan Bayramı, orucun bitişinin bayramıdır. Ramazan'ın hemen ardından, Şevval ayının 1. günündedir.","Peygamberimiz ﷺ bayram namazına çıkmadan önce tek sayıda birkaç hurma yerdi. Fıtır sadakası bu namazdan önce verilmelidir.","Bayramdan sonra Şevval ayından altı gün oruç tutmak tavsiye edilir: Ramazan ile birlikte bütün yılı oruçlu geçirmek gibidir."],
 retenir:"1 Şevval: bayram. Namazdan önce hurma, sonra Şevval'den altı gün.",
 sources:["h:aid_dattes","h:shawwal","q:2:185"],
 quiz:[
  {q:"Ramazan Bayramı hangi gündür?",c:["Şevval'in 1. günü","27 Ramazan","10 Zilhicce","1 Muharrem"],b:0,e:"Ramazan Bayramı, Ramazan ayının hemen ardından gelir.",s:["f:mois"]},
  {q:"\"Îdü'l-Fıtr\" (Ramazan Bayramı) ne anlama gelir?",c:["Orucu açma bayramı","Kurban bayramı","Hicret bayramı","Peygamberimiz ﷺ'in doğum bayramı"],b:0,e:"Fıtır, orucu açmak demektir.",s:["f:aid"]},
  {q:"Peygamberimiz ﷺ Ramazan Bayramı namazına çıkmadan önce ne yerdi?",c:["Birkaç hurma","İncir","Et","Hiçbir şey, oruçlu olurdu"],b:0,e:"Ramazan Bayramı günü birkaç hurma yemeden çıkmazdı.",s:["h:aid_dattes"]},
  {q:"Peygamberimiz ﷺ Ramazan Bayramı sabahı hurmaları kaç tane yerdi?",c:["Tek sayıda","Her zaman iki tane","Her zaman yedi tane","Çift sayıda"],b:0,e:"Enes, onları tek sayıda yediğini rivayet eder.",s:["h:aid_dattes"]},
  {q:"İslam'da yılda kaç bayram vardır?",c:["2","1","3","5"],b:0,e:"Ramazan Bayramı ve Kurban Bayramı.",s:["f:aid"]},
  {q:"Hadise göre Ramazan'dan sonra Şevval'den kaç gün oruç tutmak tavsiye edilir?",c:["6","3","10","30"],b:0,e:"Şevval'den, peş peşe veya ayrı ayrı, altı gün.",s:["h:shawwal"]},
  {q:"Hadise göre Ramazan'ı ve ardından Şevval'den altı günü oruçla geçirmek neye denktir?",c:["Bütün yılı oruçla geçirmeye","Hacca gitmeye","Bir ay daha oruç tutmaya","Özel hiçbir şeye"],b:0,e:"Bütün yılı oruçlu geçirmiş gibidir.",s:["h:shawwal"]},
  {q:"Fıtır sadakası hangi namazdan önce verilmiş olmalıdır?",c:["Bayram namazından","Cuma namazından","Akşam namazından","Teravihten"],b:0,e:"İnsanlar bayram namazına çıkmadan önce verilmelidir.",s:["h:fitr"]},
  {q:"Bakara suresi 185. âyete göre müminler Ramazan'ın gün sayısını tamamlayınca ne yaparlar?",c:["Allah'ı yüceltirler","Yeniden oruç tutmaya başlarlar","İtikâfa girerler","Medine'yi ziyarete giderler"],b:0,e:"Âyet, ulaşılan hidayet için Allah'ı yüceltmeye çağırır: bu, bayram tekbiridir.",s:["q:2:185"]},
  {q:"Hac sırasında kutlanan, İslam'ın diğer büyük bayramı hangisidir?",c:["Kurban Bayramı","Ramazan Bayramı","Mevlid Kandili","1 Muharrem"],b:0,e:"Kurban Bayramı, 10 Zilhicce'dedir.",s:["f:aid"]}
 ]},
'p-piliers':{titre:"İslam'ın beş şartı",
 texte:["İslam, Buhârî ve Müslim'in rivayet ettiği sahih bir hadiste sayılan beş temel üzerine kuruludur.","Kelime-i şehadet, iman beyanı. Namaz, günlük beş vakit namaz. Zekât, farz olan sadaka. Hac, gücü yetene Mekke'ye hac yolculuğu. Oruç, Ramazan orucu.","Bu beş şart, Müslümanın bütün yıl boyunca ibadet hayatının temelidir."],
 retenir:"Şehadet, namaz, zekât, hac, Ramazan orucu.",
 sources:["h:piliers"],
 quiz:[
  {q:"İslam'ın kaç şartı vardır?",c:["5","3","4","6"],b:0,e:"İslam beş temel üzerine kuruludur.",s:["h:piliers"]},
  {q:"Oruca Arapçada ne denir?",c:["Savm (veya sıyâm)","Salât","Zekât","Hac"],b:0,e:"Oruca savm veya sıyâm denir; onu farz kılan âyetteki kelime budur.",s:["q:2:183"]},
  {q:"Mekke'ye hac yolculuğu kime farzdır?",c:["Gücü yetene, ömründe bir kez","Herkese, her yıl","Sadece erkeklere","Sadece Ramazan'da"],b:0,e:"Hac, bedenen ve maddi olarak gücü yetene ömründe bir kez farzdır.",s:["q:3:97"]},
  {q:"Bir Müslüman her gün kaç vakit farz namaz kılar?",c:["5","3","7","2"],b:0,e:"Sabah, öğle, ikindi, akşam ve yatsı.",s:["h:cinq"]},
  {q:"İslam'ın ilk şartı nedir?",c:["Kelime-i şehadet, iman beyanı","Oruç","Hac","Zekât"],b:0,e:"Hadiste ilk sayılan şehadettir.",s:["h:piliers"]},
  {q:"İslam'ın hangi şartı farz olan sadakadır?",c:["Zekât","Namaz","Oruç","Şehadet"],b:0,e:"Zekât, belli bir sınıra ulaşan mallardan her yıl verilir.",s:["h:piliers"]},
  {q:"İslam'ın hangi şartı Ramazan ayında yerine getirilir?",c:["Oruç (savm)","Hac","Zekât","Şehadet"],b:0,e:"Ramazan orucu beş şarttan biridir.",s:["h:piliers"]},
  {q:"İslam'ın hangi şartı Mekke'ye gitmeyi gerektirir?",c:["Hac","Namaz","Oruç","Zekât"],b:0,e:"Hac, Beytullah'ı ziyaret ibadetidir.",s:["q:3:97"]},
  {q:"Hadise göre hac ömürde kaç kez farzdır?",c:["Sadece bir kez","Her yıl","Üç kez","Yedi kez"],b:0,e:"Peygamberimiz ﷺ, haccın her yıl farz olmadığını açıklamıştır.",s:["h:hajj_une"]},
  {q:"İslam'ın beş şartı hadisini hangi sahabi rivayet etmiştir?",c:["Abdullah b. Ömer","Ebû Bekir","Bilal","Hâlid b. Velîd"],b:0,e:"Hadisi İbn Ömer rivayet etmiştir.",s:["h:piliers"]}
 ]},
'p-shahada':{titre:"Kelime-i şehadet, iman beyanı",
 texte:["Kelime-i şehadet iman beyanıdır: \"Eşhedü en lâ ilâhe illallâh ve eşhedü enne Muhammeden rasûlullâh\".","Anlamı: \"Allah'tan başka ilah olmadığına şehadet ederim ve Muhammed'in Allah'ın Resulü olduğuna şehadet ederim.\"","İlk şarttır: onunla İslam'a girilir. Allah'ın birliğini, yani tevhidi ifade eder; tevhid İhlâs suresinde özetlenmiştir."],
 retenir:"Lâ ilâhe illallâh, Muhammedün rasûlullâh.",
 sources:["q:47:19","q:48:29","h:piliers"],
 quiz:[
  {q:"İslam'ın hangi şartı iman beyanıdır?",c:["Kelime-i şehadet","Namaz","Zekât","Hac"],b:0,e:"Şehadet ilk şarttır.",s:["h:piliers"]},
  {q:"\"Lâ ilâhe illallâh\" ne anlama gelir?",c:["Allah'tan başka ilah yoktur","Allah en büyüktür","Allah'ı tesbih ederim","Allah'ın adıyla"],b:0,e:"Şehadetin ilk bölümüdür.",s:["q:47:19"]},
  {q:"\"Muhammedün rasûlullâh\" ne anlama gelir?",c:["Muhammed Allah'ın Resulüdür","Muhammed bir melektir","Muhammed ilk insandır","Muhammed bir kraldır"],b:0,e:"Şehadetin ikinci bölümüdür.",s:["q:48:29"]},
  {q:"Allah'ın birliğine inanmaya ne denir?",c:["Tevhid","Hac","Sünnet","Fıkıh"],b:0,e:"Tevhid, İslam inancının özüdür.",s:["q:112:1"]},
  {q:"Hangi sure Allah'ın birliğini dört âyette özetler?",c:["İhlâs","Fâtiha","Kevser","Nâs"],b:0,e:"112. sure, İhlâs suresi.",s:["q:112:1"]},
  {q:"Kelime-i şehadet kaç bölümden oluşur?",c:["İki: Allah'ın birliği ve Muhammed ﷺ'in elçiliği","Tek bir bölüm","Beş","Yedi"],b:0,e:"Önce Allah'ın birliğine, sonra Muhammed ﷺ'in O'nun Resulü olduğuna şehadet edilir.",s:["h:piliers"]},
  {q:"İhlâs suresine göre Allah doğurmuş mu, yoksa doğurulmuş mu?",c:["Ne doğurmuş ne doğurulmuştur","Her ikisi de","Doğurmuştur","Doğurulmuştur"],b:0,e:"\"O, doğurmamış ve doğurulmamıştır.\"",s:["q:112:3"]},
  {q:"Şehadetin başındaki \"Eşhedü\" ne anlama gelir?",c:["Şehadet ederim","Namaz kılarım","Oruç tutarım","Affederim"],b:0,e:"Eşhedü, \"şehadet ederim, tanıklık ederim\" demektir.",s:["f:shahada"]},
  {q:"Bir kişi İslam'a girmek için ne yapar?",c:["Kelime-i şehadeti inanarak söyler","Bir ay oruç tutar","Hacca gider","Arapça öğrenir"],b:0,e:"İçtenlikle söylenen şehadet, kişiyi İslam'a sokar.",s:["f:shahada"]},
  {q:"Kur'an, Âl-i İmrân suresi 144. âyette Muhammed ﷺ hakkında ne der?",c:["O ancak bir elçidir, ondan önce de elçiler gelip geçmiştir","O ölümsüzdür","O bir melektir","O ilk peygamberdir"],b:0,e:"Muhammed ﷺ, kendisinden öncekiler gibi bir insan ve bir elçidir.",s:["q:3:144"]}
 ]},
'p-priere':{titre:"Namaz, günde beş buluşma",
 texte:["Müslüman günde beş vakit namaz kılar: tan yerinde sabah, öğlen öğle, öğleden sonra ikindi, güneş batınca akşam ve gece yatsı.","Her namazın belirli sayıda rekâtı vardır: sabah 2, öğle 4, ikindi 4, akşam 3 ve yatsı 4.","Mekke'deki Kâbe'ye yönelerek namaz kılınır: buna kıble denir. Her namazın vakti ezanla duyurulur. Cuma günü öğle namazının yerine cuma namazı kılınır."],
 retenir:"Sabah 2, öğle 4, ikindi 4, akşam 3, yatsı 4 — kıbleye yönelerek.",
 sources:["q:4:103","f:rakat","q:2:144"],
 quiz:[
  {q:"Sabah namazının farzı kaç rekâttır?",c:["2","3","4","1"],b:0,e:"Sabah namazının farzı 2 rekâttır.",s:["f:rakat"]},
  {q:"Akşam namazının farzı kaç rekâttır?",c:["3","2","4","5"],b:0,e:"Akşam, 3 rekât olan tek farz namazdır.",s:["f:rakat"]},
  {q:"Müslümanlar namaz kılarken hangi yöne yönelir?",c:["Mekke'deki Kâbe'ye","Kudüs'e","Medine'ye","Doğuya"],b:0,e:"Bu yöne kıble denir.",s:["q:2:144"]},
  {q:"Namaz vaktini duyuran çağrının adı nedir?",c:["Ezan","Kamet","Dua","Zikir"],b:0,e:"Ezan vakti duyurur; kamet ise cemaatle namazın başladığını bildirir.",s:["h:adhan"]},
  {q:"Tan yerinde kılınan farz namazın adı nedir?",c:["Sabah namazı","Öğle namazı","İkindi namazı","Yatsı namazı"],b:0,e:"Sabah namazı, tan yerinin ağarmasıyla güneşin doğuşu arasında kılınır.",s:["f:rakat"]},
  {q:"Öğle namazının farzı kaç rekâttır?",c:["4","2","3","5"],b:0,e:"Öğle namazı 4 rekâttır.",s:["f:rakat"]},
  {q:"Bir gündeki beş vakit namazda toplam kaç rekât farz vardır?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rekât.",s:["f:rakat"]},
  {q:"Kur'an'a göre namaz müminlere nasıl farz kılınmıştır?",c:["Belirli vakitlerde","Haftada bir kez","İstenildiği zaman","Sadece Ramazan'da"],b:0,e:"\"Namaz, müminler üzerine vakitleri belirlenmiş bir farzdır.\"",s:["q:4:103"]},
  {q:"Her cuma öğle namazının yerine hangi cemaat namazı kılınır?",c:["Cuma namazı","Bayram namazı","Teravih","Yağmur duası namazı"],b:0,e:"Kur'an, cuma günü Allah'ı anmaya koşmaya çağırır.",s:["q:62:9"]},
  {q:"Hadise göre beş vakit namaz hangi olay sırasında farz kılınmıştır?",c:["Gece yolculuğu (İsrâ ve Mîrac)","Bedir Savaşı","Hicret","Mekke'nin fethi"],b:0,e:"Elli vakit namaz farz kılındı, sonra beşe indirildi.",s:["h:cinq"]}
 ]},
'p-ablutions':{titre:"Abdest ve Fâtiha",
 texte:["Müslüman namazdan önce suyla temizlenir: buna abdest denir. Su yoksa temiz toprakla teyemmüm edilir.","Yüz yıkanır, eller ve kollar dirseklere kadar yıkanır, ıslak ellerle baş meshedilir, sonra ayaklar topuklara kadar yıkanır.","Namazın her rekâtında Kur'an'ın ilk suresi olan, 7 âyetlik Fâtiha suresi, yani \"Açılış\" okunur."],
 retenir:"Abdestsiz namaz olmaz, Fâtihasız namaz olmaz.",
 sources:["q:5:6","q:1:2","h:fatiha"],
 quiz:[
  {q:"Namazdan önce suyla yapılan temizliğin adı nedir?",c:["Abdest","Oruç","Zekât","İtikâf"],b:0,e:"Abdest, namazdan önce temizler.",s:["q:5:6"]},
  {q:"Namazın her rekâtında hangi sure okunur?",c:["Fâtiha","İhlâs","Bakara","Yâsîn"],b:0,e:"\"Açılış\" anlamındaki Fâtiha her rekâtta okunur.",s:["h:fatiha"]},
  {q:"Fâtiha suresi hangi cümleyle başlar?",c:["Bismillâhi'r-Rahmâni'r-Rahîm","Kul hüvallâhü ehad","Allâhu ekber","Sübhânallâh"],b:0,e:"\"Rahmân ve Rahîm olan Allah'ın adıyla.\"",s:["q:1:1"]},
  {q:"Kur'an'a göre abdestte kollar nereye kadar yıkanır?",c:["Dirseklere kadar","Bileklere kadar","Omuzlara kadar","Sadece parmaklar"],b:0,e:"Mâide suresinin 6. âyeti bunu açıklar.",s:["q:5:6"]},
  {q:"Kur'an'a göre abdestte başa ne yapılır?",c:["Islak ellerle meshedilir","Üç kez tamamen yıkanır","Sarıkla örtülür","Enseye su dökülür"],b:0,e:"Buna mesh denir: ıslak elleri başın üzerinden geçirmek.",s:["q:5:6"]},
  {q:"Namazdan önce temizlenmek için su bulunamazsa ne yapılır?",c:["Temiz toprakla teyemmüm edilir","Namaz kılınmaz","Ertesi gün beklenir","Temizlenmeden namaz kılınır"],b:0,e:"Aynı âyet, su bulunmadığında teyemmümü öngörür.",s:["q:5:6"]},
  {q:"Hadise göre abdesti bozulup yenilemeyen kişinin namazını Allah kabul eder mi?",c:["Hayır, abdestini yenileyene kadar kabul etmez","Evet, her zaman","Evet, cuma günü","Sadece sabah namazını"],b:0,e:"Namaz ancak abdest yenilendikten sonra kabul edilir.",s:["h:wudu"]},
  {q:"Fâtiha suresi kaç âyettir?",c:["7","5","10","3"],b:0,e:"Ona \"tekrarlanan yedi âyet\" denir.",s:["q:15:87"]},
  {q:"\"Elhamdü lillâhi rabbi'l-âlemîn\" ne anlama gelir?",c:["Hamd, âlemlerin Rabbi Allah'adır","Allah en büyüktür","Allah'tan başka ilah yoktur","Allah'a sığınırım"],b:0,e:"Fâtiha'nın 2. âyetidir.",s:["q:1:2"]},
  {q:"Hadise göre Fâtiha'yı okumayanın namazı nasıldır?",c:["Geçerli değildir","İki kat sayılır","Geçerlidir","Yarım sayılır"],b:0,e:"\"Fâtiha'yı okumayanın namazı yoktur.\"",s:["h:fatiha"]}
 ]},
'p-zakat':{titre:"Zekât, farz olan sadaka",
 texte:["Zekât, İslam'ın beş şartından biri olan farz sadakadır. Adı arınmayı ve bereketlenip artmayı çağrıştırır: malı arındırır ve en muhtaçlara yardım eder.","Birikimi asgari bir sınıra (nisap) ulaşan ve bu birikim tam bir kameri yıl elinde kalan kişiyi ilgilendirir. Paradan verilen zekât %2,5'tir.","Kur'an, aralarında fakirlerin ve yoksulların bulunduğu sekiz grup zekât alıcısı sayar. Sadaka ise her zaman verilebilen gönüllü bir bağıştır."],
 retenir:"Zekât: bir kameri yıl boyunca nisaba ulaşan birikimin %2,5'i.",
 sources:["q:9:60","q:9:103","f:zakat"],
 quiz:[
  {q:"İslam'ın hangi şartı farz olan sadakadır?",c:["Zekât","Sadaka","Hac","Oruç"],b:0,e:"Zekât farzdır; sadaka gönüllüdür.",s:["h:piliers"]},
  {q:"Biriktirilen paradan verilen zekâtın oranı nedir?",c:["%2,5","%10","%20","%5"],b:0,e:"Yani birikimin kırkta biri.",s:["f:zakat"]},
  {q:"Zekâtın farz olduğu asgari zenginlik sınırına ne denir?",c:["Nisap","Sâ'","Fidye","Havl"],b:0,e:"Nisabın altında zekât farz değildir.",s:["f:zakat"]},
  {q:"Zekâtın farz olması için birikim ne kadar süre elde bulunmalıdır?",c:["Bir kameri yıl","Bir ay","On yıl","Sadece Ramazan ayı"],b:0,e:"Buna havl denir: tam bir kameri yıl.",s:["f:zakat"]},
  {q:"Kur'an'a göre zekâtı kaç grup insan alabilir?",c:["8","5","3","12"],b:0,e:"Tevbe suresinin 60. âyeti sekiz grup sayar.",s:["q:9:60"]},
  {q:"Kur'an'da sayılan zekât alıcıları arasında kimler vardır?",c:["Fakirler ve yoksullar","En zenginler","Tüccarlar","Cami imamları"],b:0,e:"Fakirler ve yoksullar ilk sırada sayılır.",s:["q:9:60"]},
  {q:"Zekât ile sadaka arasındaki fark nedir?",c:["Zekât farzdır, sadaka gönüllüdür","Hiçbir fark yoktur","Sadaka farzdır","Zekât haramdır"],b:0,e:"Sadaka her zaman ve her miktarda verilebilir.",s:["f:zakat"]},
  {q:"Kur'an'da zekât çoğu zaman hangi ibadetle birlikte anılır?",c:["Namaz","Oruç","Hac","Abdest"],b:0,e:"\"Namazı kılın, zekâtı verin\": bu ifade pek çok kez tekrarlanır.",s:["q:2:43"]},
  {q:"İslam'ın şartları hadisindeki sıralamada zekât kaçıncı sıradadır?",c:["3.","1.","5.","2."],b:0,e:"Şehadet, namaz, zekât, hac, Ramazan orucu.",s:["h:piliers"]},
  {q:"Arapçada \"zekât\" kelimesi neyi çağrıştırır?",c:["Arınmayı ve artmayı","Sabrı","Zaferi","Işığı"],b:0,e:"Kur'an, sadakanın arındırdığını (tutahhiruhum) ve hayırda artırdığını (tuzekkîhim) söyler.",s:["q:9:103"]}
 ]},
'p-hajj':{titre:"Hac, kutsal yolculuk",
 texte:["Hac, İslam'ın beş şartından biri olan Mekke'ye yapılan kutsal yolculuktur. Bedenen ve maddi olarak gücü yetene ömründe bir kez farzdır.","Zilhicce ayında yapılır. Hacı ihrama girer, Kâbe'nin etrafında yedi kez döner (tavaf) ve Safa ile Merve arasında yedi kez gidip gelir (sa'y). En önemli an, 9 Zilhicce'deki Arafat vakfesidir.","Ertesi gün bütün dünyadaki Müslümanlar, Hz. İbrahim'in hatırasına Kurban Bayramı'nı kutlar."],
 retenir:"Ömürde bir kez. Arafat 9 Zilhicce'de, Kurban Bayramı 10'unda.",
 sources:["q:3:97","q:22:27","h:hajj_pardon"],
 quiz:[
  {q:"Hac hangi şehirde yapılır?",c:["Mekke","Medine","Kudüs","Taif"],b:0,e:"Hac, Mekke'de ve çevresinde yapılır.",s:["q:3:97"]},
  {q:"Hac, İslami takvimin hangi ayında yapılır?",c:["Zilhicce","Ramazan","Muharrem","Şevval"],b:0,e:"Hac, 8-13 Zilhicce arasında yapılır.",s:["f:hajj"]},
  {q:"Hadise göre haccın en önemli unsuru nedir?",c:["Arafat vakfesi","Mescid-i Aksâ'da namaz","Medine ziyareti","Hira mağarası ziyareti"],b:0,e:"\"Hac, Arafat'tır.\"",s:["h:arafa"]},
  {q:"Arefe gününün ertesi günü hangi bayram kutlanır?",c:["Kurban Bayramı","Ramazan Bayramı","Mevlid Kandili","1 Muharrem"],b:0,e:"10 Zilhicce, Kurban Bayramı'dır.",s:["f:hajj"]},
  {q:"Hadise göre günah işlemeden ve çirkin söz söylemeden haccını yapan hacı nasıl döner?",c:["Annesinin onu doğurduğu gündeki gibi","Daha zengin","Oruçtan muaf","Sadece \"hacı\" unvanıyla, başka bir mükâfat olmadan"],b:0,e:"Günahlarından arınmış olarak döner.",s:["h:hajj_pardon"]},
  {q:"İnsanları hacca çağırmakla hangi peygamber görevlendirildi?",c:["İbrahim","Musa","Nuh","Yusuf"],b:0,e:"Allah, insanları hacca çağırmasını Hz. İbrahim'e emretti.",s:["q:22:27"]},
  {q:"Hacının girdiği kutsiyet hâlinin adı nedir?",c:["İhram","Abdest","İtikâf","Teyemmüm"],b:0,e:"Erkekler dikişsiz iki parça beyaz kumaş giyer.",s:["f:hajj"]},
  {q:"Kâbe'nin etrafında yapılan yedi turun adı nedir?",c:["Tavaf","Sa'y","Rekât","Zikir"],b:0,e:"Tavaf, Kâbe sol tarafta kalacak şekilde yedi tur olarak yapılır.",s:["f:hajj"]},
  {q:"Hacı hangi iki tepe arasında yedi kez gidip gelir?",c:["Safa ve Merve","Arafat ve Mina","Uhud ve Sevr","Hira ve Sevr"],b:0,e:"Kur'an, Safa ile Merve'yi Allah'ın nişaneleri arasında sayar.",s:["q:2:158"]},
  {q:"Müslümanlar Kurban Bayramı'nda hangi peygamberin hatırasına kurban keser?",c:["İbrahim","İsa","Musa","Davud"],b:0,e:"Allah, Hz. İbrahim'in oğluna bedel olarak büyük bir kurban verdi.",s:["q:37:107"]}
 ]},
'c-coran':{titre:"Kur'an, Allah'ın kelamı",
 texte:["Kur'an, Cebrail meleği aracılığıyla Peygamber Hz. Muhammed ﷺ'e Arapça olarak indirilen Allah'ın kelamıdır.","İlk vahiy, Mekke yakınlarındaki Hira mağarasında, Peygamberimiz ﷺ 40 yaşındayken geldi. İlk inen kelimeler \"İkra\" yani \"Oku!\" diye başlar.","Vahiy yaklaşık 23 yıl sürdü. Kur'an 114 suredir; Allah onu korumayı üstlenmiştir."],
 retenir:"114 sure, 23 yılda indi. İlk kelime: \"İkra\", \"Oku!\".",
 sources:["q:96:1","h:hira","q:15:9"],
 quiz:[
  {q:"Kur'an kaç suredir?",c:["114","99","120","30"],b:0,e:"Kur'an 114 suredir.",s:["f:coran"]},
  {q:"Kur'an'ı Peygamber Hz. Muhammed ﷺ'e hangi melek getirdi?",c:["Cebrail","Mikâil","İsrâfil","Mâlik"],b:0,e:"Vahyi getiren melek Cebrail'dir.",s:["q:2:97"]},
  {q:"Peygamberimiz ﷺ Kur'an'ın ilk vahyini hangi mağarada aldı?",c:["Hira mağarası","Sevr mağarası","Medine'de bir mağara","Kudüs'te bir mağara"],b:0,e:"Hira mağarası, Mekke yakınlarındaki Nur Dağı'ndadır.",s:["h:hira"]},
  {q:"Kur'an'ın ilk inen kelimesi \"İkra\" ne anlama gelir?",c:["Oku!","Namaz kıl!","Dinle!","Oruç tut!"],b:0,e:"Alak suresinin (96) başlangıcıdır.",s:["q:96:1"]},
  {q:"Kur'an yaklaşık kaç yılda indirildi?",c:["23 yıl","1 yıl","40 yıl","10 yıl"],b:0,e:"Yaklaşık 13 yıl Mekke'de, 10 yıl Medine'de.",s:["h:vie"]},
  {q:"Kur'an okunurken kaç cüze ayrılır?",c:["30","114","7","12"],b:0,e:"Otuz cüz: örneğin Ramazan'da her gün bir cüz.",s:["f:coran"]},
  {q:"Kur'an hangi dilde indirildi?",c:["Arapça","İbranice","Farsça","Aramice"],b:0,e:"\"Biz onu Arapça bir Kur'an olarak indirdik.\"",s:["q:12:2"]},
  {q:"Kur'an'a göre Kur'an'ın korunmasını kim üstlenmiştir?",c:["Allah","Sadece âlimler","Halifeler","Hiç kimse"],b:0,e:"\"Kur'an'ı Biz indirdik, onun koruyucusu da elbette Biziz.\"",s:["q:15:9"]},
  {q:"İlk vahiy geldiğinde Peygamberimiz ﷺ kaç yaşındaydı?",c:["40","25","63","13"],b:0,e:"Vahiy almaya 40 yaşında başladı.",s:["h:vie"]},
  {q:"Kur'an'daki bir cümleye Arapçada ne denir?",c:["Âyet","Sure","Cüz","Hadis"],b:0,e:"Kur'an cümlesine âyet, bölümüne sure denir.",s:["f:coran"]}
 ]},
'c-sourates':{titre:"Sureler",
 texte:["Kur'an, uzunlukları birbirinden çok farklı 114 sureden oluşur. Tevbe suresi hariç her biri besmeleyle başlar.","İlki Fâtiha, yani \"Açılış\"tır. En uzunu 286 âyetiyle Bakara, yani \"İnek\" suresidir. En kısası 3 âyetiyle Kevser'dir. Sonuncusu Nâs, yani \"İnsanlar\" suresidir.","Hicret'ten önce inen surelere Mekkî, sonra inenlere Medenî sureler denir."],
 retenir:"İlk: Fâtiha. En uzun: Bakara. En kısa: Kevser. Son: Nâs.",
 sources:["q:1:1","q:108:1","q:114:1"],
 quiz:[
  {q:"Kur'an'ın ilk suresi hangisidir?",c:["Fâtiha","Bakara","Nâs","Alak"],b:0,e:"Fâtiha Kur'an'ı açar. İlk inen âyetler Alak suresindedir ama o 96. suredir.",s:["q:1:1"]},
  {q:"Kur'an'ın en uzun suresi hangisidir?",c:["Bakara","Fâtiha","Kevser","Yâsîn"],b:0,e:"2. sure olan Bakara 286 âyettir.",s:["f:coran"]},
  {q:"Kur'an'ın en kısa suresi hangisidir?",c:["Kevser","İhlâs","Nâs","Asr"],b:0,e:"108. sure olan Kevser 3 âyettir.",s:["q:108:1"]},
  {q:"Kur'an'ın son suresi hangisidir?",c:["Nâs","Felak","İhlâs","Fâtiha"],b:0,e:"\"İnsanlar\" anlamındaki Nâs, 114. suredir.",s:["q:114:1"]},
  {q:"Hangi sure \"Kul hüvallâhü ehad\" ile başlar?",c:["İhlâs","Nâs","Felak","Kâfirûn"],b:0,e:"\"De ki: O, Allah'tır, birdir.\"",s:["q:112:1"]},
  {q:"\"Bu, kendisinde hiçbir şüphe olmayan Kitap'tır\" âyeti hangi suredir?",c:["Bakara","Fâtiha","Meryem","Yâsîn"],b:0,e:"Bakara suresinin 2. âyetidir.",s:["q:2:2"]},
  {q:"Hangi sure, Hz. İsa'nın annesinin adını taşır?",c:["Meryem","Âl-i İmrân","Nisâ","Tâhâ"],b:0,e:"19. sure Meryem'in adını taşır.",s:["q:19:16"]},
  {q:"\"Bismillâhi'r-Rahmâni'r-Rahîm\" ile başlamayan tek sure hangisidir?",c:["Tevbe (9. sure)","Fâtiha","Nâs","Bakara"],b:0,e:"Tevbe, 114 sure arasında başında besmele olmayan tek suredir.",s:["f:tawba"]},
  {q:"\"Bismillâhi'r-Rahmâni'r-Rahîm\" ifadesine ne denir?",c:["Besmele","Şehadet","Tekbir","Telbiye"],b:0,e:"Anlamı: \"Rahmân ve Rahîm olan Allah'ın adıyla.\"",s:["q:1:1"]},
  {q:"Mekke'de, Hicret'ten önce inen surelere ne denir?",c:["Mekkî sureler","Medenî sureler","Uzun sureler","Taif sureleri"],b:0,e:"Hicret'ten sonra inenlere Medenî sureler denir.",s:["f:coran"]}
 ]},
'c-ikhlas':{titre:"İhlâs ve Âyetü'l-Kürsî",
 texte:["İhlâs suresi (112), Allah'ın birliğine imanı özetler: O birdir, doğurmamış ve doğurulmamıştır, hiçbir şey O'na denk değildir.","Peygamberimiz ﷺ onun Kur'an'ın üçte birine denk olduğunu söylemiştir.","Âyetü'l-Kürsî (Bakara suresi, 255. âyet), Kur'an'ın en büyük âyetidir. Allah'ın hayatını, ilmini ve kudretini anlatır."],
 retenir:"İhlâs Kur'an'ın üçte birine denktir. Âyetü'l-Kürsî en büyük âyettir.",
 sources:["q:112:1","h:ikhlas","h:kursi"],
 quiz:[
  {q:"\"Kul hüvallâhü ehad\" ne anlama gelir?",c:["De ki: O, Allah'tır, birdir","Allah'ın adıyla","Allah en büyüktür","Allah'ı tesbih ederim"],b:0,e:"İhlâs suresinin ilk âyetidir.",s:["q:112:1"]},
  {q:"Hadise göre İhlâs suresi Kur'an'ın ne kadarına denktir?",c:["Üçte birine","Yarısına","Onda birine","Tamamına"],b:0,e:"Peygamberimiz ﷺ onun Kur'an'ın üçte birine denk olduğunu söylemiştir.",s:["h:ikhlas"]},
  {q:"İhlâs suresi kaç âyettir?",c:["4","7","3","5"],b:0,e:"İhlâs suresi 4 âyettir.",s:["q:112:4"]},
  {q:"İhlâs suresine göre Allah'a denk olan biri var mıdır?",c:["Hayır, hiçbir şey O'na denk değildir","Evet, melekler","Evet, peygamberler","Evet, cinler"],b:0,e:"\"Hiçbir şey O'na denk değildir.\"",s:["q:112:4"]},
  {q:"Hadise göre Kur'an'ın en büyük âyeti hangisidir?",c:["Âyetü'l-Kürsî","Fâtiha'nın ilk âyeti","Kur'an'ın son âyeti","Nur âyeti"],b:0,e:"Übey b. Kâ'b bunu Peygamberimiz ﷺ'e söyledi, o da onayladı.",s:["h:kursi"]},
  {q:"Âyetü'l-Kürsî hangi suredir?",c:["Bakara, 255. âyet","Fâtiha, 1. âyet","Yâsîn, 1. âyet","İhlâs, 2. âyet"],b:0,e:"Âyetü'l-Kürsî, Bakara suresinin 255. âyetidir.",s:["q:2:255"]},
  {q:"Âyetü'l-Kürsî'ye göre Allah'ı uyuklama veya uyku tutar mı?",c:["Hayır, O'nu ne uyuklama ne de uyku tutar","Evet, gece","Evet, bazen","Sadece uyku"],b:0,e:"Allah, Hayy'dır (diri), Kayyûm'dur (her şeyi ayakta tutan).",s:["q:2:255"]},
  {q:"İhlâs suresindeki \"Allâhü's-Samed\" ne anlama gelir?",c:["Allah, herkesin O'na muhtaç olduğu, kimseye muhtaç olmayandır","Allah, göğün yaratıcısıdır","Allah, bağışlayandır","Allah, hükmedendir"],b:0,e:"Es-Samed, Allah'ın isimlerinden biridir.",s:["q:112:2"]},
  {q:"\"İhlâs\" suresinin adı ne anlama gelir?",c:["Saf tevhid, samimiyet","Tan vakti","Zafer","İnsanlar"],b:0,e:"İmanı her türlü şirkten arındırır.",s:["f:ikhlas"]},
  {q:"Âyetü'l-Kürsî'ye göre yaratılmışlar Allah'ın ilminden ne kadarını kavrayabilir?",c:["Sadece O'nun dilediği kadarını","O'nun bütün ilmini","Hiçbir şeyini","Yarısını"],b:0,e:"\"O'nun ilminden, dilediği kadarından başka bir şey kavrayamazlar.\"",s:["q:2:255"]}
 ]},
'pr-adam':{titre:"Âdem ve Nuh",
 texte:["Hz. Âdem ilk insan ve ilk peygamberdir. Allah ona her şeyin ismini öğretti, sonra meleklere ona secde etmelerini emretti. İblis kibrinden dolayı reddetti.","Hz. Nuh 950 yıl boyunca kavmini yalnız Allah'a ibadete çağırdı. Ona çok az kişi uydu, kendi oğlu bile uymadı.","Allah'ın emriyle Nuh gemiyi yaptı; bu gemi onu müminlerle ve hayvan çiftleriyle birlikte tufandan kurtardı."],
 retenir:"Âdem, ilk insan. Nuh, 950 yıllık tebliğ ve gemi.",
 sources:["q:2:31","q:2:34","q:29:14"],
 quiz:[
  {q:"İnsanlığın ilk peygamberi kimdir?",c:["Âdem","Nuh","İbrahim","Musa"],b:0,e:"Hz. Âdem ilk insan ve ilk peygamberdir.",s:["q:2:31"]},
  {q:"Allah Âdem'e ne öğretti?",c:["Her şeyin ismini","Kur'an'ı ezbere","Sadece meleklerin dilini","Sadece peygamberlerin isimlerini"],b:0,e:"\"Ve Âdem'e isimlerin hepsini öğretti.\"",s:["q:2:31"]},
  {q:"Âdem'e secde etmeyi kim reddetti?",c:["İblis","Cebrail","Mikâil","Bütün melekler"],b:0,e:"İblis dışında melekler secde etti.",s:["q:2:34"]},
  {q:"İblis Âdem'e secde etmeyi neden reddetti?",c:["Kibrinden","Unuttuğu için","Korkudan","Emri duymadığı için"],b:0,e:"Reddetti, büyüklük tasladı ve kâfirlerden oldu.",s:["q:2:34"]},
  {q:"Âdem ve eşi yeryüzüne inmeden önce nerede yaşıyordu?",c:["Cennette","Mekke'de","Mısır'da","Kudüs'te"],b:0,e:"\"Sen ve eşin cennete yerleşin.\"",s:["q:2:35"]},
  {q:"Allah'ın emriyle gemiyi hangi peygamber yaptı?",c:["Nuh","Yunus","Süleyman","İsa"],b:0,e:"Nuh, gemiyi Allah'ın gözetiminde ve O'nun vahyine göre yaptı.",s:["q:11:37"]},
  {q:"Kur'an'a göre Nuh kavminin arasında ne kadar kaldı?",c:["950 yıl","40 yıl","100 yıl","313 yıl"],b:0,e:"\"Elli yıl eksik bin yıl.\"",s:["q:29:14"]},
  {q:"Nuh'un gemisinde kimler kurtuldu?",c:["Nuh, müminler ve hayvan çiftleri","Bütün kavmi","Sadece hayvanlar","Hiç kimse"],b:0,e:"Allah, her türden bir çifti, ailesini ve müminleri gemiye bindirmesini emretti.",s:["q:11:40"]},
  {q:"Nuh'un oğlu gemiye bindi mi?",c:["Hayır, reddetti ve boğuldu","Evet, ilk o bindi","Evet, en son","Oğlu yoktu"],b:0,e:"Bir dağa sığınmayı düşündü ama dalgalar onu aldı götürdü.",s:["q:11:43"]},
  {q:"İslami geleneğe göre Âdem'in eşinin adı nedir?",c:["Havva","Meryem","Âsiye","Hacer"],b:0,e:"Kur'an ondan ismini vermeden bahseder; adı sünnetten gelir.",s:["f:hawwa"]}
 ]},
'pr-ibrahim':{titre:"İbrahim, Allah'ın dostu",
 texte:["Hz. İbrahim kavminin putlarına tapmayı reddetti. Onu büyük bir ateşe attılar, ama Allah ateşe, onun için serinlik ve esenlik olmasını emretti.","Allah onu yakın dost (Halîl) edindi. O, iki peygamberin babasıdır: İsmail ve İshak.","Oğlu İsmail ile birlikte Kâbe'nin temellerini yükseltti. Kurban Bayramı'ndaki kurban, onun Allah'a teslimiyetini hatırlatır."],
 retenir:"İbrahim, Allah'ın dostu, ateşten kurtarılan, İsmail ile Kâbe'yi inşa eden.",
 sources:["q:21:69","q:4:125","q:2:127"],
 quiz:[
  {q:"Oğlu İsmail ile birlikte Kâbe'nin temellerini hangi peygamber yükseltti?",c:["İbrahim","Musa","Davud","Âdem"],b:0,e:"İbrahim ve oğlu İsmail, Kâbe'nin temellerini yükselttiler.",s:["q:2:127"]},
  {q:"Kavmi Hz. İbrahim'i ateşe attığında ne oldu?",c:["Allah ateşi onun için serin ve zararsız kıldı","Kaçtı","Yaralandı","Yağmur sayesinde kurtuldu"],b:0,e:"\"Ey ateş! İbrahim'e karşı serin ve esenlik ol.\"",s:["q:21:69"]},
  {q:"Kur'an Hz. İbrahim'e hangi unvanı verir?",c:["Allah'ın yakın dostu (Halîl)","Peygamberlerin sonuncusu","Allah'ın kendisiyle konuştuğu kişi","Allah'ın ruhu"],b:0,e:"\"Allah, İbrahim'i dost edinmişti.\"",s:["q:4:125"]},
  {q:"Hz. İbrahim'in peygamber olan iki oğlu kimlerdir?",c:["İsmail ve İshak","Musa ve Harun","Davud ve Süleyman","Yahya ve İsa"],b:0,e:"İbrahim, yaşlılığında kendisine İsmail'i ve İshak'ı verdiği için Allah'a şükretti.",s:["q:14:39"]},
  {q:"Hz. İbrahim'in kavmi ne yapıyordu ki o bunu reddediyordu?",c:["Heykellere tapıyorlardı","Oruç tutuyorlardı","Sadaka veriyorlardı","Hacca gidiyorlardı"],b:0,e:"Onlara sordu: \"Kendilerine tapıp durduğunuz bu heykeller nedir?\"",s:["q:21:52"]},
  {q:"Kurban anında Allah, Hz. İbrahim'in oğluna bedel olarak ne verdi?",c:["Büyük bir kurbanlık (kesilecek bir hayvan)","Altından bir sadaka","Babasının orucunu","Bir gece namazını"],b:0,e:"Rivayetlere göre bu bir koçtu.",s:["q:37:107"]},
  {q:"Hangi bayram Hz. İbrahim'in Allah'a teslimiyetini hatırlatır?",c:["Kurban Bayramı","Ramazan Bayramı","1 Muharrem","Mevlid Kandili"],b:0,e:"Kurban Bayramı'ndaki kurban, onun imtihanını anar.",s:["q:37:107"]},
  {q:"Kur'an'a göre Hz. İbrahim nasıl tanımlanır?",c:["Hanîf bir mümin; ne Yahudi ne Hristiyan","Babil kralı","Bir melek","Bir şair"],b:0,e:"O, tamamen Allah'a teslim olmuştu.",s:["q:3:67"]},
  {q:"Kâbe'nin temellerini yükseltmede Hz. İbrahim'e hangi oğlu yardım etti?",c:["İsmail","İshak","Yakub","Yusuf"],b:0,e:"İbrahim ve İsmail, Beyt'in temellerini birlikte yükseltiyorlardı.",s:["q:2:127"]},
  {q:"Kur'an'a göre insanlar için kurulan ilk ibadet evi hangisidir?",c:["Bekke'deki (Mekke) ev","Kudüs'teki ev","Medine'deki ev","Taif'teki ev"],b:0,e:"Bekke, Mekke'nin bir adıdır.",s:["q:3:96"]}
 ]},
'pr-yunus':{titre:"Yunus, Yusuf ve Süleyman",
 texte:["Hz. Yunus'u büyük bir balık yuttu. Karanlıklar içinde Allah'a dua etti, Allah da onu sıkıntıdan kurtardı.","Kardeşleri tarafından ihanete uğrayan, sonra Mısır'da bakan olan Hz. Yusuf'un kıssası 12. surenin tamamını kaplar: \"kıssaların en güzeli\".","Davud'un oğlu Hz. Süleyman'a çok büyük bir mülk verildi; kuşların ve karıncaların dilini anlardı."],
 retenir:"Yunus ve balık. Yusuf, 12. sure. Süleyman ve hayvanların dili.",
 sources:["q:37:142","q:12:3","q:27:18"],
 quiz:[
  {q:"Hangi peygamberi büyük bir balık yuttu?",c:["Yunus","Yusuf","Eyyub","Lût"],b:0,e:"Yunus'u balık yuttu, sonra Allah onu kurtardı.",s:["q:37:142"]},
  {q:"Kur'an'daki hangi sure Hz. Yusuf'un kıssasını baştan sona anlatır?",c:["12. sure, Yusuf","1. sure, Fâtiha","36. sure, Yâsîn","112. sure, İhlâs"],b:0,e:"12. sure onun adını taşır.",s:["q:12:3"]},
  {q:"Hangi peygamber karıncaların dilini anlardı?",c:["Süleyman","Salih","Hûd","Zekeriya"],b:0,e:"Süleyman, bir karıncanın diğerlerini uyardığını duydu ve onun sözüne gülümsedi.",s:["q:27:18"]},
  {q:"Hz. Yunus balığın karnında hangi duayı okudu?",c:["\"Lâ ilâhe illâ ente sübhâneke innî küntü mine'z-zâlimîn\"","\"Bismi Llâh\"","\"Allâhu ekber\"","\"Rabbenâ âtinâ\""],b:0,e:"\"Senden başka ilah yoktur. Seni tenzih ederim. Gerçekten ben zalimlerden oldum.\"",s:["q:21:87"]},
  {q:"Allah, Hz. Yunus'un duasına nasıl karşılık verdi?",c:["Onu sıkıntıdan kurtardı","Onu balığın içinde bıraktı","Onu üç yıl balığın içinde bıraktı","Karşılık vermedi"],b:0,e:"\"Biz de onun duasını kabul ettik ve onu sıkıntıdan kurtardık.\"",s:["q:21:88"]},
  {q:"Hz. Yusuf çocukken gördüğü rüyada kaç yıldızın kendisine secde ettiğini gördü?",c:["On bir; güneş ve ay ile birlikte","Yedi","On iki","Sadece bir"],b:0,e:"On bir yıldız, güneş ve ay.",s:["q:12:4"]},
  {q:"Hz. Yusuf'u kuyunun dibine kim attı?",c:["Kardeşleri","Firavun","Tüccarlar","Babası"],b:0,e:"Kıskanç kardeşleri onu kuyunun dibine atmaya karar verdiler.",s:["q:12:15"]},
  {q:"Kur'an, Hz. Yusuf'un kıssasını nasıl adlandırır?",c:["Kıssaların en güzeli","Ateş kıssası","Hikmet kitabı","Gemi kıssası"],b:0,e:"\"Biz sana kıssaların en güzelini anlatıyoruz.\"",s:["q:12:3"]},
  {q:"Kuşların dilinin bilgisi hangi peygambere verildi?",c:["Süleyman","Yunus","Nuh","Hûd"],b:0,e:"Süleyman: \"Bize kuş dili öğretildi\" dedi.",s:["q:27:16"]},
  {q:"Kendisi de peygamber ve kral olan Hz. Süleyman'ın babası kimdi?",c:["Davud","İbrahim","Yakub","Musa"],b:0,e:"\"Süleyman, Davud'a vâris oldu.\"",s:["q:27:16"]}
 ]},
'pr-musa':{titre:"Musa, Allah'ın kendisiyle konuştuğu peygamber",
 texte:["Hz. Musa, Firavun'un İsrailoğullarına zulmettiği dönemde Mısır'da doğdu. Allah'ın ilhamıyla annesi onu nehre bıraktı ve Firavun'un ailesi onu buldu.","Allah onunla doğrudan konuştu ve onu kardeşi Harun ile birlikte, yılana dönüşen asası gibi mucizelerle Firavun'a gönderdi.","Allah, Musa'yı ve kavmini kurtarmak için denizi yardı, Firavun ise boğuldu. Musa, Kur'an'da adı en çok geçen peygamberdir."],
 retenir:"Musa, sudan kurtarılan, Kelîmullah, yarılan deniz.",
 sources:["q:28:7","q:4:164","q:26:63"],
 quiz:[
  {q:"Hz. Musa hangi ülkede doğdu?",c:["Mısır'da","Arabistan'da","Irak'ta","Yemen'de"],b:0,e:"Firavun'un hükümdarlığı döneminde Mısır'da doğdu.",s:["q:28:7"]},
  {q:"Hz. Musa'nın annesi onu Firavun'dan korumak için ne yaptı?",c:["Onu nehre bıraktı","Onu bir mağaraya sakladı","Çöle gitti","Onu bir çobana emanet etti"],b:0,e:"Allah ona, korkmadan onu nehre bırakmasını ilham etti.",s:["q:28:7"]},
  {q:"Bebek Musa'yı nehirden kim aldı?",c:["Firavun'un ailesi","Balıkçılar","İbrahim","Bir Yemen kralı"],b:0,e:"Firavun'un adamları onu aldılar.",s:["q:28:8"]},
  {q:"Allah'ın doğrudan konuştuğu kişi anlamında \"Kelîmullah\" diye anılan peygamber kimdir?",c:["Musa","İbrahim","İsa","Nuh"],b:0,e:"\"Allah, Musa ile gerçekten konuştu.\"",s:["q:4:164"]},
  {q:"Hz. Musa asasını yere atınca asa neye dönüştü?",c:["Bir yılana","Bir ağaca","Bir güvercine","Bir kılıca"],b:0,e:"\"Onu attı, bir de ne görsün, o koşan bir yılan oluverdi.\"",s:["q:20:20"]},
  {q:"Hz. Musa asasıyla denize vurunca ne oldu?",c:["Deniz ikiye yarıldı","Kuma dönüştü","Bir anda kurudu","Hiçbir şey olmadı"],b:0,e:"Her bölüm büyük bir dağ gibiydi.",s:["q:26:63"]},
  {q:"Musa'yı takip eden Firavun ve ordusuna ne oldu?",c:["Denizde boğuldular","İman ettiler","Mısır'a geri döndüler","Onlar da karşıya geçtiler"],b:0,e:"Allah Musa'yı ve yanındakileri kurtardı, ötekileri boğdu.",s:["q:26:66"]},
  {q:"Görevinde Hz. Musa'ya yardım eden kardeşinin adı neydi?",c:["Harun","Yusuf","İshak","Yahya"],b:0,e:"Musa, kardeşi Harun'u kendisine yardımcı yapmasını Allah'tan istedi.",s:["q:20:30"]},
  {q:"Allah Hz. Musa'yı hangi krala gönderdi?",c:["Firavun","Nemrut","Sebe kralı","Câlût"],b:0,e:"\"Firavun'a git, çünkü o çok azdı.\"",s:["q:20:24"]},
  {q:"Kur'an'da adı en çok geçen peygamber hangisidir?",c:["Musa","Muhammed ﷺ","İbrahim","Nuh"],b:0,e:"Musa'nın adı Kur'an'da 130'dan fazla kez geçer.",s:["f:musa"]}
 ]},
'pr-isa':{titre:"İsa ve Meryem",
 texte:["Hz. İsa'nın annesi Meryem, Kur'an'da adı geçen tek kadındır. Allah onu âlemlerin kadınlarına üstün kılmıştır ve bir sure onun adını taşır.","Hz. İsa, tıpkı Âdem'in babasız ve annesiz yaratılması gibi, Allah'ın iradesiyle babasız doğdu. Bebekken beşikte konuştu.","Müslümanlar için İsa, büyük bir peygamber ve Allah'ın elçisidir; kendisine İncil indirilen Mesih'tir."],
 retenir:"Meryem, kadınlar arasından seçilmiş. İsa, babasız doğmuş, peygamber ve Mesih.",
 sources:["q:3:42","q:3:59","q:19:30"],
 quiz:[
  {q:"Kur'an'da adı geçen tek kadın kimdir?",c:["Meryem","Hatice","Âsiye","Havva"],b:0,e:"Adıyla anılan tek kadın Meryem'dir; 19. sure onun adını taşır.",s:["f:maryam"]},
  {q:"Kur'an Meryem hakkında ne der?",c:["Allah onu âlemlerin kadınlarına üstün kılmıştır","Mısır kraliçesiydi","Medine'nin peygamberiydi","Kur'an ondan bahsetmez"],b:0,e:"Melekler ona, Allah'ın onu seçtiğini ve temizlediğini müjdeledi.",s:["q:3:42"]},
  {q:"Hz. İsa nasıl doğdu?",c:["Babasız, Allah'ın iradesiyle","Herkes gibi","Firavun'un sarayında","Mekke'de"],b:0,e:"Allah \"Ol\" der, o da olur.",s:["q:3:59"]},
  {q:"Kur'an, Hz. İsa'nın yaratılışını kimin yaratılışına benzetir?",c:["Âdem'inkine","Meleklerinkine","Nuh'unkine","İblis'inkine"],b:0,e:"Âdem babasız ve annesiz yaratıldı; İsa ise babasız.",s:["q:3:59"]},
  {q:"Hz. İsa bebekken hangi mucizeyi gösterdi?",c:["Beşikte konuştu","Su üstünde yürüdü","Zemzem suyunu fışkırttı","Denizi geçti"],b:0,e:"Beşikten konuşarak annesini savundu.",s:["q:19:30"]},
  {q:"Kur'an'a göre bebek İsa'nın ilk sözleri nelerdi?",c:["\"Ben Allah'ın kuluyum\"","\"Ben kralım\"","\"Ben bir meleğim\"","\"Ben Zekeriya'nın oğluyum\""],b:0,e:"\"Ben Allah'ın kuluyum. O bana Kitap'ı verdi ve beni peygamber yaptı.\"",s:["q:19:30"]},
  {q:"Kur'an Hz. İsa'ya hangi unvanı verir?",c:["el-Mesîh, Mesih","Halîl","Peygamberlerin sonuncusu","Kelîmullah"],b:0,e:"Melekler Meryem'e müjdeler: \"Onun adı Meryem oğlu İsa Mesih'tir.\"",s:["q:3:45"]},
  {q:"Allah Hz. İsa'ya hangi kitabı indirdi?",c:["İncil","Tevrat","Zebur","Kur'an"],b:0,e:"\"Ona içinde hidayet ve nur bulunan İncil'i verdik.\"",s:["q:5:46"]},
  {q:"Müslümanlar için İsa kimdir?",c:["Allah'ın bir peygamberi ve elçisi","Bir ilah","Bir melek","Bir Kudüs kralı"],b:0,e:"Kendini Allah'ın kulu ve peygamberi olarak tanıtır.",s:["q:19:30"]},
  {q:"İsa'nın doğumunu müjdelemek için Meryem'e kim gönderildi?",c:["Allah'ın ruhu, Cebrail meleği","Zekeriya","Yahya","Mikâil meleği"],b:0,e:"Âlimler, \"Ruhumuz\" ifadesinin Cebrail meleğini kastettiğini açıklar.",s:["q:19:19"]}
 ]},
'pr-muhammad':{titre:"Muhammed ﷺ, son peygamber",
 texte:["Hz. Muhammed ﷺ, 570 yılı civarında, \"Fil Yılı\"nda, Mekke'de Kureyş kabilesinde doğdu. Babası o doğmadan vefat etmişti; 6 yaşında annesi Âmine'yi kaybetti; önce dedesi, sonra amcası Ebû Tâlib onu büyüttü.","Dürüstlüğüyle tanınırdı, ona \"güvenilir\" anlamında el-Emîn denirdi. İlk vahyi 40 yaşında aldı.","632'de, 63 yaşında Medine'de vefat etti. Allah onu âlemlere rahmet olarak göndermiştir."],
 retenir:"570 civarı Mekke'de doğdu, 40 yaşında vahiy, 63 yaşında Medine'de vefat.",
 sources:["q:21:107","q:68:4","h:vie"],
 quiz:[
  {q:"Peygamber Hz. Muhammed ﷺ hangi şehirde doğdu?",c:["Mekke","Medine","Kudüs","Taif"],b:0,e:"570 civarında Mekke'de doğdu.",s:["f:sira"]},
  {q:"Peygamberimiz ﷺ'in doğduğu yıla ne denir?",c:["Fil Yılı","Hicret Yılı","Hüzün Yılı","Zafer Yılı"],b:0,e:"Fillerle gelen bir ordunun Mekke'ye saldırdığı yıl (105. sure).",s:["q:105:1"]},
  {q:"Peygamberimiz ﷺ'in annesinin adı neydi?",c:["Âmine","Hatice","Halime","Fâtıma"],b:0,e:"Vehb kızı Âmine, o 6 yaşındayken vefat etti.",s:["f:sira"]},
  {q:"Peygamberimiz ﷺ'i hangi amcası büyüttü ve korudu?",c:["Ebû Tâlib","Ebû Leheb","Hamza","Abbas"],b:0,e:"Dedesinin vefatından sonra amcası Ebû Tâlib onu himayesine aldı.",s:["f:sira"]},
  {q:"Mekkeliler vahiyden önce Peygamberimiz ﷺ'e hangi lakabı verirdi?",c:["el-Emîn, güvenilir","el-Fârûk","es-Sıddîk","Seyfullah"],b:0,e:"Herkes onu dürüstlüğüyle tanırdı.",s:["f:sira"]},
  {q:"Peygamberimiz ﷺ kaç yaşında vefat etti?",c:["63","40","70","53"],b:0,e:"İbn Abbas, onun 63 yaşında vefat ettiğini rivayet eder.",s:["h:vie"]},
  {q:"Peygamberimiz ﷺ hangi şehirde vefat etti?",c:["Medine","Mekke","Kudüs","Şam"],b:0,e:"632'de Medine'de vefat etti ve oraya defnedildi.",s:["f:sira"]},
  {q:"Kur'an'a göre Allah Hz. Muhammed ﷺ'i neden gönderdi?",c:["Âlemlere rahmet olarak","Kral olmak için","İnsanları cezalandırmak için","Sadece Araplar için"],b:0,e:"\"Biz seni ancak âlemlere rahmet olarak gönderdik.\"",s:["q:21:107"]},
  {q:"Kur'an Peygamberimiz ﷺ'in ahlakı hakkında ne der?",c:["O, yüce bir ahlak üzeredir","O serttir","O ilgisizdir","Kur'an bundan bahsetmez"],b:0,e:"\"Şüphesiz sen yüce bir ahlak üzeresin.\"",s:["q:68:4"]},
  {q:"Peygamberimiz ﷺ hangi kabileye mensuptu?",c:["Kureyş","Evs","Hazrec","Sakîf"],b:0,e:"Kureyş, Mekke'nin büyük kabilesi.",s:["f:sira"]}
 ]},
'pr-livres':{titre:"İndirilen kitaplar ve iman",
 texte:["Allah bazı peygamberlere kitaplar indirdi: Tevrat'ı Musa'ya, Zebur'u Davud'a, İncil'i İsa'ya ve Kur'an'ı Muhammed ﷺ'e.","Kur'an 25 peygamberin adını verir, ama Allah çok daha fazlasını göndermiştir. Mümin, ayrım yapmadan hepsine inanır.","İman altı esasa dayanır: Allah'a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe ve kadere inanmak."],
 retenir:"Tevrat, Zebur, İncil, Kur'an. İmanın altı esası.",
 sources:["q:5:44","q:2:285","h:jibril"],
 quiz:[
  {q:"Allah Hz. Musa'ya hangi kitabı indirdi?",c:["Tevrat","Zebur","İncil","Kur'an"],b:0,e:"Tevrat Musa'ya, Zebur Davud'a, İncil İsa'ya, Kur'an Muhammed ﷺ'e.",s:["q:5:44"]},
  {q:"Kur'an'da kaç peygamberin adı geçer?",c:["25","12","40","313"],b:0,e:"25 peygamberin adı geçer; bunlardan 18'i En'âm suresinde birlikte anılır.",s:["f:prophetes25"]},
  {q:"Kur'an hangi peygambere \"peygamberlerin sonuncusu\" (Hâtemü'n-nebiyyîn) der?",c:["Muhammed ﷺ","İsa","Musa","İbrahim"],b:0,e:"Muhammed ﷺ peygamberlerin sonuncusudur.",s:["q:33:40"]},
  {q:"Hz. Davud'a hangi kitap indirildi?",c:["Zebur","Tevrat","İncil","İbrahim'in sahifeleri"],b:0,e:"\"Davud'a da Zebur'u verdik.\"",s:["q:4:163"]},
  {q:"İndirilen kitaplara inanmak Müslümanın imanının bir parçası mıdır?",c:["Evet, imanın bir esasıdır","Hayır, sadece Kur'an'a","Hayır, isteğe bağlıdır","Sadece Ramazan'da"],b:0,e:"Müminler Allah'a, meleklerine, kitaplarına ve peygamberlerine inanır.",s:["q:2:285"]},
  {q:"İmanın kaç esası vardır?",c:["6","5","4","10"],b:0,e:"Allah, melekler, kitaplar, peygamberler, ahiret günü ve kader.",s:["h:jibril"]},
  {q:"Aşağıdakilerden hangisi imanın esaslarından biri DEĞİLDİR?",c:["Ramazan orucu","Meleklere iman","Ahiret gününe iman","Kitaplara iman"],b:0,e:"Oruç, imanın (inanç) değil, İslam'ın (uygulama) şartlarındandır.",s:["h:jibril"]},
  {q:"Allah hangi kitabı korumayı üstlenmiştir?",c:["Kur'an","Tevrat","Zebur","Kralların bütün kitapları"],b:0,e:"\"Onun koruyucusu da elbette Biziz.\"",s:["q:15:9"]},
  {q:"Kur'an, Allah'ın gönderdiği bütün peygamberlerin kıssasını anlatır mı?",c:["Hayır, sadece bazılarının","Evet, hepsinin","Hiçbirini anlatmaz","Sadece Arapların"],b:0,e:"\"Sana kıssalarını anlattığımız peygamberler de var, anlatmadığımız peygamberler de.\"",s:["q:4:164"]},
  {q:"Kur'an'a göre müminler imanlarında peygamberler arasında ayrım yapar mı?",c:["Hayır, hepsine inanırlar","Evet, sadece birine inanırlar","Evet, eskilerini reddederler","Hiçbirine inanmazlar"],b:0,e:"\"O'nun peygamberleri arasında hiçbir ayrım yapmayız.\"",s:["q:2:285"]}
 ]},
'h-khadija':{titre:"Hz. Hatice ve İslam'ın ilk yılları",
 texte:["Hz. Hatice, Mekke'nin saygın bir tüccarıydı. O sırada 25 yaşında olan Peygamberimiz ﷺ ile evlendi.","İlk vahiyden sonra onu teselli eden ve ona ilk iman eden o oldu. Onu amcasının oğlu Varaka b. Nevfel'e götürdü.","İlk Müslümanlar arasında Ebû Bekir, Ali, Zeyd b. Hârise ve Bilal vardır. Mekke'de 13 yıl boyunca Müslümanlar zulme uğradı; Sümeyye ilk şehit kadın oldu."],
 retenir:"Hatice, ilk iman eden. Mekke'de 13 yıl tebliğ.",
 sources:["h:hira","f:debuts"],
 quiz:[
  {q:"Peygamberimiz ﷺ'in ilk eşi kimdi?",c:["Hatice","Âişe","Hafsa","Zeynep"],b:0,e:"Hatice, onun mesajına ilk iman eden kişiydi.",s:["h:hira"]},
  {q:"Hira mağarasındaki ilk vahiyden hemen sonra Peygamberimiz ﷺ'i kim teselli etti?",c:["Hatice","Ebû Bekir","Ali","Bilal"],b:0,e:"Hatice'nin yanına döndü, o da onu yatıştırdı.",s:["h:hira"]},
  {q:"Hz. Hatice Mekke'de hangi işle uğraşıyordu?",c:["Ticaret","Hekimlik","Şairlik","Deve yetiştiriciliği"],b:0,e:"Zengin ve saygın bir tüccardı.",s:["f:debuts"]},
  {q:"Peygamberimiz ﷺ Hz. Hatice ile evlendiğinde kaç yaşındaydı?",c:["25","40","18","30"],b:0,e:"25 yaşındaydı.",s:["f:debuts"]},
  {q:"İlk vahiyden sonra Hz. Hatice Peygamberimiz ﷺ'i kimin yanına götürdü?",c:["Amcasının oğlu Varaka b. Nevfel'in","Ebû Tâlib'in","Ebû Bekir'in","Habeşistan kralının"],b:0,e:"Varaka eski kutsal kitapları bilirdi.",s:["h:hira"]},
  {q:"İslam'ı ilk kabul edenler arasında hangi küçük çocuk vardı?",c:["Ali b. Ebû Tâlib","Ömer","Hâlid","Muâviye"],b:0,e:"Peygamberimiz ﷺ'in amcasının oğlu Ali henüz çocuktu.",s:["f:debuts"]},
  {q:"Peygamberimiz ﷺ Hicret'ten önce Mekke'de yaklaşık kaç yıl tebliğ yaptı?",c:["13 yıl","3 yıl","23 yıl","40 yıl"],b:0,e:"İbn Abbas, vahiyden sonra Mekke'de 13 yıl kaldığını rivayet eder.",s:["h:vie"]},
  {q:"Peygamberimiz ﷺ'in hangi dostu İslam'ı kabul eden ilk yetişkin erkekti?",c:["Ebû Bekir","Ömer","Osman","Hamza"],b:0,e:"Ebû Bekir ona hiç tereddüt etmeden iman etti.",s:["f:debuts"]},
  {q:"İmanı yüzünden zulme uğrayan hangi eski köle İslam'ın ilk müezzini oldu?",c:["Bilal b. Rebâh","Zeyd b. Hârise","Selmân","Enes"],b:0,e:"Sesi uzaklara ulaşırdı: Peygamberimiz ﷺ ezanı ona emanet etti.",s:["h:adhan"]},
  {q:"İslam'ın ilk şehit kadınının adı neydi?",c:["Sümeyye","Hatice","Fâtıma","Esmâ"],b:0,e:"Ammâr'ın annesi Sümeyye, Mekke'de imanı yüzünden öldürüldü.",s:["f:debuts"]}
 ]},
'h-hegire':{titre:"Hicret",
 texte:["622'de zulümler karşısında Peygamberimiz ﷺ, Mekke'den o zamanki adıyla Yesrib olan Medine'ye göç etti: buna Hicret denir. Hicret, İslami takvimin 1. yılıdır.","Yolculuk sırasında dostu Ebû Bekir ile Sevr mağarasında saklandı.","Medine'de onu Ensar (\"yardımcılar\") karşıladı; onlar mallarını Muhacirlerle (\"göç edenler\") paylaştı. Orada mescidini inşa etti."],
 retenir:"622: Hicret, 1. yıl. Muhacirler ve Ensar.",
 sources:["q:9:40","f:hegire"],
 quiz:[
  {q:"Hicret nedir?",c:["Peygamberimiz ﷺ'in Mekke'den Medine'ye göçü","İlk hac","Bir savaş","Peygamberimiz ﷺ'in doğumu"],b:0,e:"İslami takvimin 1. yılıdır.",s:["f:hegire"]},
  {q:"Hicret sırasında mağarada Peygamberimiz ﷺ'e hangi sahabi eşlik ediyordu?",c:["Ebû Bekir es-Sıddîk","Ömer b. Hattâb","Ali b. Ebû Tâlib","Bilal"],b:0,e:"Ebû Bekir mağarada \"ikinin ikincisi\" idi.",s:["q:9:40"]},
  {q:"Hicret hangi yılda gerçekleşti?",c:["622","570","632","610"],b:0,e:"Hicret, miladi 622 yılında gerçekleşti.",s:["f:hegire"]},
  {q:"Peygamberimiz ﷺ Hicret sırasında hangi mağarada saklandı?",c:["Sevr mağarası","Hira mağarası","Uhud mağarası","Bedir mağarası"],b:0,e:"Sevr Mekke'nin güneyinde; ilk vahyin geldiği Hira ise kuzeyindedir.",s:["f:hegire"]},
  {q:"Medine'nin eski adı neydi?",c:["Yesrib","Bekke","Taif","Kuba"],b:0,e:"Kur'an bu adı anar: \"Ey Yesrib halkı\".",s:["q:33:13"]},
  {q:"Müslümanları karşılayan Medinelilere ne denir?",c:["Ensar","Muhacirler","Kureyş","İsrailoğulları"],b:0,e:"Ensar, \"yardımcılar\" demektir.",s:["q:9:100"]},
  {q:"Mekke'den Medine'ye göç eden Müslümanlara ne denir?",c:["Muhacirler","Ensar","Hariciler","Bedeviler"],b:0,e:"Muhacir, \"göç eden\" demektir.",s:["q:9:100"]},
  {q:"Kur'an'a göre Peygamberimiz ﷺ mağarada Ebû Bekir'e ne dedi?",c:["\"Üzülme, Allah bizimle beraberdir\"","\"Çabuk kaçalım\"","\"Mekke'ye dönelim\"","\"Onlarla savaşalım\""],b:0,e:"Tevbe suresinin 40. âyetidir.",s:["q:9:40"]},
  {q:"Hicri takvim hangi halifenin döneminde benimsendi?",c:["Ömer","Ebû Bekir","Osman","Ali"],b:0,e:"Ömer, Hicret'i takvimin başlangıcı yaptı.",s:["f:hegire"]},
  {q:"Peygamberimiz ﷺ Medine'ye varınca ne inşa etti?",c:["Mescidini","Bir saray","Bir kale","Bir çarşı"],b:0,e:"Peygamber Mescidi (Mescid-i Nebevî).",s:["f:hegire"]}
 ]},
'h-badr':{titre:"Bedir Savaşı",
 texte:["Hicret'in 2. yılında (624), 17 Ramazan'da Müslümanlar, Bedir kuyuları yakınında Kureyş ordusuyla karşılaştı.","Yaklaşık 1000 savaşçıya karşı yaklaşık 313 kişiydiler. Allah onları meleklerle destekledi ve zafer kazandılar.","Kur'an bu güne, hakkın batıldan ayrıldığı gün olan \"Furkan günü\" (yevmü'l-furkân) der."],
 retenir:"2. yıl 17 Ramazan: Bedir, 1000'e karşı 313, Furkan günü.",
 sources:["q:3:123","q:8:9","q:8:41"],
 quiz:[
  {q:"Bedir Savaşı hangi ayda oldu?",c:["Ramazan","Muharrem","Zilhicce","Recep"],b:0,e:"Hicret'in 2. yılında, 17 Ramazan'da.",s:["f:badr"]},
  {q:"Bedir Savaşı Hicret'in kaçıncı yılında oldu?",c:["2. yıl","8. yıl","10. yıl","1. yıl"],b:0,e:"Miladi 624 yılında.",s:["f:badr"]},
  {q:"Bedir'de yaklaşık kaç Müslüman savaştı?",c:["Yaklaşık 313","Yaklaşık 3.000","Yaklaşık 10.000","Yaklaşık 50"],b:0,e:"Yaklaşık 313 kişiydiler.",s:["f:badr"]},
  {q:"Bedir'de Kureyş ordusu yaklaşık kaç savaşçıdan oluşuyordu?",c:["1000'e yakın","100'e yakın","10.000'e yakın","300'e yakın"],b:0,e:"Mekkeliler üç kat daha kalabalıktı.",s:["f:badr"]},
  {q:"Kur'an'a göre Allah Bedir'de Müslümanları nasıl destekledi?",c:["Meleklerle","Bir kum fırtınasıyla","İran'dan gelen takviyelerle","Sadece yağmurla"],b:0,e:"Allah onların yakarışına melekler göndererek karşılık verdi.",s:["q:8:9"]},
  {q:"Enfâl suresine göre Allah Bedir'de takviye olarak kaç melek göndermeyi vaat etti?",c:["Bin","Yüz","On","Üç yüz"],b:0,e:"\"Ben size art arda gelen bin melekle yardım edeceğim.\"",s:["q:8:9"]},
  {q:"Kur'an Bedir gününe ne ad verir?",c:["Furkan günü (yevmü'l-furkân)","Kıyamet günü","Bayram günü","Hicret günü"],b:0,e:"Hakkın batıldan ayrıldığı gün.",s:["q:8:41"]},
  {q:"Müslümanlar Bedir'de hangi kabileye karşı savaştı?",c:["Kureyş","Bizanslılar","İranlılar","Ensar"],b:0,e:"Kureyş ordusu Mekke'den gelmişti.",s:["f:badr"]},
  {q:"Bedir Savaşı Ramazan'ın kaçıncı gününde oldu?",c:["17","27","1","10"],b:0,e:"2. yılın 17 Ramazan'ında.",s:["f:badr"]},
  {q:"Kur'an'a göre Müslümanlar Bedir'de ne durumdaydı?",c:["Zayıf ve güçsüzdüler","Çok kalabalıktılar","Zengindiler","Atlıydılar"],b:0,e:"\"Andolsun, siz güçsüz iken Allah size Bedir'de yardım etmişti.\"",s:["q:3:123"]}
 ]},
'h-fath':{titre:"Mekke'nin fethi",
 texte:["Hicret'in 8. yılında (630), Ramazan ayında Peygamberimiz ﷺ yaklaşık 10.000 Müslümanla, neredeyse hiç savaşmadan Mekke'ye girdi.","Eski düşmanlarını affetti ve Kâbe'yi 360 puttan temizledi; bunu yaparken şunu okuyordu: \"Hak geldi, batıl yok oldu.\"","Nasr suresi, Allah'ın bu yardımını ve insanların bölük bölük İslam'a girişini haber verir."],
 retenir:"8. yıl Ramazan: Mekke fethedildi, putlar kırıldı, af ilan edildi.",
 sources:["q:17:81","h:idoles","q:110:1"],
 quiz:[
  {q:"Mekke Hicret'in kaçıncı yılında fethedildi?",c:["8. yıl","2. yıl","1. yıl","11. yıl"],b:0,e:"Miladi 630 yılında.",s:["f:fath"]},
  {q:"Mekke'nin fethi hangi ayda oldu?",c:["Ramazan","Şevval","Zilhicce","Muharrem"],b:0,e:"Mekke'nin fethi Ramazan'da gerçekleşti.",s:["f:fath"]},
  {q:"Mekke'nin fethinde Peygamberimiz ﷺ'e yaklaşık kaç Müslüman eşlik ediyordu?",c:["Yaklaşık 10.000","Yaklaşık 313","Yaklaşık 1000","Yaklaşık 100"],b:0,e:"Yaklaşık 10.000 kişilik bir ordu.",s:["f:fath"]},
  {q:"Mekke'nin fethedildiği gün Kâbe'nin çevresinde kaç put vardı?",c:["360","12","99","1000"],b:0,e:"Abdullah b. Mes'ûd, 360 put olduğunu rivayet eder.",s:["h:idoles"]},
  {q:"Peygamberimiz ﷺ Kâbe'deki putları devirirken hangi âyeti okudu?",c:["\"Hak geldi, batıl yok oldu\"","\"Allah'ın adıyla\"","\"De ki: O, Allah'tır, birdir\"","\"Oku!\""],b:0,e:"İsrâ suresinin 81. âyetidir.",s:["q:17:81","h:idoles"]},
  {q:"Peygamberimiz ﷺ fetihten sonra Mekkeli eski düşmanlarına nasıl davrandı?",c:["Onları affetti","Onları kovdu","Onları hapsetti","Onları Habeşistan'a sürgün etti"],b:0,e:"Mekkelilere genel af ilan etti.",s:["f:fath"]},
  {q:"Hangi sure \"Allah'ın yardımı ve fetih\"i haber verir?",c:["Nasr (110)","Fetih (48)","Fil (105)","Kevser (108)"],b:0,e:"\"Allah'ın yardımı ve fetih geldiğinde.\"",s:["q:110:1"]},
  {q:"Nasr suresine göre insanlar İslam'a nasıl girdi?",c:["Bölük bölük","Teker teker, gizlice","Zorla","Hiç kimse girmedi"],b:0,e:"\"Ve insanların bölük bölük Allah'ın dinine girdiğini gördüğünde.\"",s:["q:110:2"]},
  {q:"Mekke'nin fethi büyük bir savaşla mı gerçekleşti?",c:["Hayır, neredeyse hiç savaşmadan","Evet, tarihin en büyük savaşıyla","Evet, bir yıl boyunca","Evet, Uhud dağının eteğinde"],b:0,e:"Şehir, neredeyse hiç çatışma olmadan barışçıl şekilde fethedildi.",s:["f:fath"]},
  {q:"Nasr suresi zaferden sonra ne yapılmasını ister?",c:["Allah'ı tesbih etmeyi ve O'ndan bağışlanma dilemeyi","Hemen hacca gitmeyi","Üç gün oruç tutmayı","Kâbe'yi yeniden inşa etmeyi"],b:0,e:"\"Rabbini hamd ile tesbih et ve O'ndan bağışlanma dile.\"",s:["q:110:3"]}
 ]},
'h-califes':{titre:"İlk dört halife",
 texte:["Peygamberimiz ﷺ'in 632'deki vefatından sonra dört halife birbirini izledi: Ebû Bekir, Ömer, Osman ve Ali. Onlara \"Hulefâ-i Râşidîn\" (doğru yolda olan halifeler) denir.","Ebû Bekir, Kur'an'ı Zeyd b. Sâbit'e tek bir mushafta toplattı. Ömer döneminde İslam yayıldı ve Hicri takvim benimsendi.","Osman, Kur'an'ı çoğaltarak nüshalarını vilayetlere gönderdi. Peygamberimiz ﷺ'in amcasının oğlu ve damadı olan Ali dördüncü halife oldu."],
 retenir:"Ebû Bekir, Ömer, Osman, Ali: dört râşid halife.",
 sources:["h:compilation","h:copies","f:califes"],
 quiz:[
  {q:"Peygamberimiz ﷺ'in vefatından sonra ilk halife kim oldu?",c:["Ebû Bekir","Ömer","Ali","Osman"],b:0,e:"Ebû Bekir, sonra Ömer, Osman ve Ali.",s:["f:califes"]},
  {q:"Peygamberimiz ﷺ'in ardından kaç \"râşid halife\" geldi?",c:["4","3","5","12"],b:0,e:"Onlara el-hulefâü'r-râşidûn denir.",s:["f:califes"]},
  {q:"İlk dört halifenin sırası nedir?",c:["Ebû Bekir, Ömer, Osman, Ali","Ali, Ömer, Ebû Bekir, Osman","Ömer, Ebû Bekir, Ali, Osman","Osman, Ali, Ömer, Ebû Bekir"],b:0,e:"632'den 661'e kadar.",s:["f:califes"]},
  {q:"Kur'an ilk kez hangi halife döneminde tek bir mushafta toplandı?",c:["Ebû Bekir","Ömer","Osman","Ali"],b:0,e:"Pek çok hafızın şehit düştüğü Yemâme Savaşı'ndan sonra.",s:["h:compilation"]},
  {q:"Ebû Bekir döneminde Kur'an'ı toplamakla hangi sahabi görevlendirildi?",c:["Zeyd b. Sâbit","Bilal","Hâlid b. Velîd","Selmân"],b:0,e:"Zeyd b. Sâbit vahiy kâtibiydi.",s:["h:compilation"]},
  {q:"Hangi halife Kur'an'ı çoğaltarak nüshalarını vilayetlere gönderdi?",c:["Osman","Ebû Bekir","Ömer","Ali"],b:0,e:"Bütün İslam dünyasında kıraati birleştirmek için.",s:["h:copies"]},
  {q:"Ali ile Peygamberimiz ﷺ arasında nasıl bir akrabalık vardı?",c:["Amcasının oğlu ve damadıydı","Kardeşiydi","Amcasıydı","Dedesiydi"],b:0,e:"Ali, Peygamberimiz ﷺ'in kızı Fâtıma'nın eşiydi.",s:["f:califes"]},
  {q:"Doğruyu yanlıştan ayıran anlamında \"el-Fârûk\" lakabıyla anılan halife kimdir?",c:["Ömer","Ebû Bekir","Osman","Ali"],b:0,e:"Ömer b. Hattâb.",s:["f:califes"]},
  {q:"\"Doğru sözlü, sadık\" anlamında \"es-Sıddîk\" lakabıyla anılan halife kimdir?",c:["Ebû Bekir","Ömer","Osman","Ali"],b:0,e:"Ebû Bekir, Peygamberimiz ﷺ'in haber verdiği her şeye hemen inandı.",s:["f:califes"]},
  {q:"Hangi halife Peygamberimiz ﷺ'in iki kızıyla art arda evlendi?",c:["Osman","Ömer","Ebû Bekir","Ali"],b:0,e:"Bu yüzden \"iki nur sahibi\" anlamında \"Zinnûreyn\" lakabını aldı.",s:["f:califes"]}
 ]}
},
faits:{
mois:{titre:"Bilgi notu",texte:"12 Hicri ay: Muharrem, Safer, Rebîülevvel, Rebîülâhir, Cemâziyelevvel, Cemâziyelâhir, Recep, Şaban, Ramazan, Şevval, Zilkade, Zilhicce."},
jeune2:{titre:"Tarihî bilgi",texte:"Ramazan orucu Medine'de, Hicret'in 2. yılında (624) farz kılınmıştır."},
conditions:{titre:"Bilgi notu",texte:"Âlimler orucun farz olmasının şartları olarak şunları sayar: Müslüman, ergenliğe ermiş, akıllı ve oruç tutmaya gücü yeter olmak."},
aid:{titre:"Bilgi notu",texte:"İslam'da iki bayram vardır: Ramazan'ın sonunda, 1 Şevval'de Ramazan Bayramı ve hac sırasında, 10 Zilhicce'de Kurban Bayramı."},
shahada:{titre:"Bilgi notu",texte:"Kelime-i şehadetin metni: \"Eşhedü en lâ ilâhe illallâh ve eşhedü enne Muhammeden rasûlullâh\" — \"Allah'tan başka ilah olmadığına şehadet ederim ve Muhammed'in Allah'ın Resulü olduğuna şehadet ederim\"."},
rakat:{titre:"Nakledilen uygulama",texte:"Her namazın rekât sayısı, Peygamberimiz ﷺ'in uygulamasından gelir ve bütün Müslümanlarca nesilden nesile aktarılmıştır: sabah 2, öğle 4, ikindi 4, akşam 3, yatsı 4; yani günde 17 rekât."},
zakat:{titre:"Bilgi notu",texte:"Paranın zekâtı, nisaba ulaşan ve bir kameri yıl (havl) elde kalan birikimin %2,5'idir (kırkta biri). Sadaka gönüllü bir bağıştır. Özel durumlar için bir âlime danışmak gerekir."},
hajj:{titre:"Bilgi notu",texte:"Hac, 8-13 Zilhicce arasında yapılır. Hacı ihrama girer (erkekler dikişsiz iki parça beyaz kumaş giyer), tavaf (Kâbe'nin etrafında yedi tur) ve sa'y (Safa ile Merve arasında yedi kez gidiş geliş) yapar. 9'u Arefe günü, 10'u Kurban Bayramı'dır."},
coran:{titre:"Bilgi notu",texte:"En yaygın sayıma göre Kur'an 114 sure ve 6236 âyettir. 30 cüze ayrılmıştır. Kur'an cümlesine âyet denir. Hicret'ten önce inen surelere Mekkî, sonrakilere Medenî sureler denir. En uzunu Bakara'dır (286 âyet)."},
tawba:{titre:"Bilgi notu",texte:"Tevbe suresi (9), 114 sure arasında \"Bismillâhi'r-Rahmâni'r-Rahîm\" ile başlamayan tek suredir."},
ikhlas:{titre:"Bilgi notu",texte:"İhlâs, \"saf tevhid, samimiyet\" demektir: sure, imanı her türlü şirkten arındırır."},
hawwa:{titre:"Bilgi notu",texte:"Kur'an, Âdem'in eşinden ismini vermeden bahseder. Adı olan Havva, sünnetten ve âlimlerden gelir."},
musa:{titre:"Bilgi notu",texte:"Musa, Kur'an'da adı en çok geçen peygamberdir: 130'dan fazla kez."},
maryam:{titre:"Bilgi notu",texte:"Meryem, Kur'an'da adıyla anılan tek kadındır. 19. sure onun adını taşır."},
sira:{titre:"Tarihî bilgi",texte:"Peygamberimiz ﷺ 570 civarında Mekke'de, Kureyş kabilesinde doğdu. Babasız büyüdü, 6 yaşında annesi Âmine'yi kaybetti; önce dedesi Abdülmuttalib, sonra amcası Ebû Tâlib onu büyüttü. Ona el-Emîn denirdi. 632'de Medine'de vefat etti."},
prophetes25:{titre:"Bilgi notu",texte:"Kur'an'da 25 peygamberin adı geçer. Bunlardan 18'i En'âm suresinde (6), 83-86. âyetlerde birlikte anılır."},
debuts:{titre:"Tarihî bilgi",texte:"Zengin bir tüccar olan Hatice, Peygamberimiz ﷺ 25 yaşındayken onunla evlendi. İlk Müslümanlar arasında Hatice, Ebû Bekir, Ali (henüz çocuk) ve Zeyd b. Hârise vardır. Zulme uğrayan, sonra azat edilen köle Bilal ilk müezzin oldu. Ammâr'ın annesi Sümeyye ilk şehit kadındı."},
hegire:{titre:"Tarihî bilgi",texte:"Hicret 622'de gerçekleşti. Peygamberimiz ﷺ ve Ebû Bekir Sevr mağarasında saklandılar. Medine'nin adı Yesrib'di. Peygamberimiz ﷺ orada mescidini inşa etti. Hicri takvim Ömer'in hilafeti döneminde benimsendi."},
badr:{titre:"Tarihî bilgi",texte:"Bedir Savaşı 2. yılın (624) 17 Ramazan'ında oldu. Yaklaşık 313 Müslüman, Kureyş'in 1000'e yakın savaşçısıyla karşılaştı."},
fath:{titre:"Tarihî bilgi",texte:"Mekke, 8. yılın (630) Ramazan ayında, yaklaşık 10.000 Müslüman tarafından neredeyse hiç savaşmadan fethedildi. Peygamberimiz ﷺ Mekkelilere genel af ilan etti."},
califes:{titre:"Tarihî bilgi",texte:"Dört râşid halife: Ebû Bekir es-Sıddîk (632-634), Ömer el-Fârûk (634-644), Peygamberimiz ﷺ'in iki kızı Rukiye ve ardından Ümmü Külsûm ile evlenen Osman Zinnûreyn (644-656) ve Peygamberimiz ﷺ'in amcasının oğlu ve kızı Fâtıma'nın eşi Ali (656-661)."}
},
resumes:{
cinq:"Gece yolculuğu (İsrâ ve Mîrac) sırasında önce elli vakit namaz farz kılındı, sonra günde beş vakte indirildi.",
enfants:"Rubeyyi' bint Muavviz, sahabenin Âşûrâ gününde küçük çocuklarına oruç tutturduğunu ve iftara kadar sabretmeleri için onlara yünden oyuncaklar verdiğini anlatır.",
hira:"Hz. Âişe, Peygamberimiz ﷺ'in Hira mağarasında inzivaya çekildiğini anlatır. Melek geldi ve ona \"Oku!\" dedi. Hatice'nin yanına döndü; Hatice onu teselli etti, sonra amcasının oğlu Varaka b. Nevfel'e götürdü.",
regles:"Hz. Âişe, âdet döneminde tutulamayan orucun kaza edilmesinin emredildiğini, namazın ise kaza edilmesinin emredilmediğini açıklar.",
tarawih:"Peygamberimiz ﷺ Ramazan'da gece camide namaz kıldı; insanlar giderek artan sayıda onun arkasında namaz kıldı. Sonra bu namazın onlara farz kılınmasından endişe ederek çıkmayı bıraktı.",
adhan:"Sahabi Abdullah b. Zeyd, rüyasında ezanın sözlerini gördü. Peygamberimiz ﷺ bu rüyayı onayladı ve sesi daha gür olduğu için Bilal'den ezanı okumasını istedi.",
ikhlas:"Bir adam İhlâs suresini durmadan okuyor ve bunu az buluyordu. Peygamberimiz ﷺ şöyle buyurdu: \"O, Kur'an'ın üçte birine denktir.\"",
kursi:"Peygamberimiz ﷺ Übey b. Kâ'b'a Allah'ın Kitabı'ndaki en büyük âyetin hangisi olduğunu sordu. O: Âyetü'l-Kürsî, dedi. Peygamberimiz ﷺ onu ilminden dolayı tebrik etti.",
hajj_une:"Peygamberimiz ﷺ haccın farz kılındığını duyurdu. Bir adam: \"Her yıl mı?\" diye sordu. O da, evet derse bunun her yıl farz olacağını söyledi: hac bir kez farzdır.",
arafa:"İnsanlar Arafat'ta Peygamberimiz ﷺ'e hac hakkında soru sordular. O şöyle cevap verdi: \"Hac, Arafat'tır.\"",
jibril:"Cebrail meleği insan suretinde gelip Peygamberimiz ﷺ'e İslam'ı, imanı ve ihsanı sordu. İman: Allah'a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe ve hayrıyla şerriyle kadere inanmaktır.",
vie:"İbn Abbas, Peygamberimiz ﷺ'in 40 yaşında vahiy aldığını, Mekke'de 13 yıl kaldığını, Medine'ye hicret edip orada 10 yıl yaşadığını ve 63 yaşında vefat ettiğini rivayet eder.",
idoles:"Fetih günü Kâbe'nin etrafında 360 put vardı. Peygamberimiz ﷺ bir sopayla onlara vuruyor ve şunu okuyordu: \"Hak geldi, batıl yok oldu.\"",
compilation:"Pek çok hafızın şehit düştüğü Yemâme Savaşı'ndan sonra Ebû Bekir, Kur'an'ı tek bir mushafta toplamakla Zeyd b. Sâbit'i görevlendirdi.",
copies:"Vilayetler arasındaki kıraat farklılıklarından endişe eden Osman, Kur'an mushafını çoğaltarak her bölgeye birer nüsha gönderdi.",
fitr_but:"İbn Abbas, Peygamberimiz ﷺ'in fıtır sadakasını oruçluyu boş ve çirkin sözlerden arındırmak ve fakirleri doyurmak için farz kıldığını rivayet eder.",
afw:"Hz. Âişe, Kadir Gecesi'ne denk gelirse ne demesi gerektiğini sordu. O şöyle cevap verdi: \"De ki: Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî\" — Allah'ım, Sen affedicisin, affetmeyi seversin, beni de affet."
}
};
